verses.push(...[{"n":"frg1","latin":"pro illis corcotis, strophiis, sumptu uxorio.","spanish":"En lugar de aquellas túnicas azafranadas, los sujetadores y los gastos de una esposa.","speaker":"EUCLIÓN (atribución conjetural)","words":[["pro","pro","preposición con ablativo","en lugar de"],["illis","ille","ablativo plural","aquellas"],["corcotis","corcota","ablativo femenino plural; vestimenta de color azafrán","túnicas azafranadas"],["strophiis","strophium","ablativo neutro plural","bandas para el pecho"],["sumptu","sumptus","ablativo masculino singular","gasto"],["uxorio","uxorius","ablativo masculino singular","conyugal"]],"section":"fragmenta"},{"n":"frg2","latin":"ut admemordit hominem!","spanish":"¡Cómo le hincó los dientes a ese hombre!","speaker":"EUCLIÓN (atribución conjetural)","words":[["ut","ut","adverbio exclamativo","cómo"],["admemordit","admordeo","perfecto indicativo tercera singular","mordió"],["hominem","homo","acusativo masculino singular","al hombre"]],"section":"fragmenta"},{"n":"frg3","latin":"ego ecfodiebam in die denos scrobes","spanish":"Yo excavaba diez hoyos al día.","speaker":"INTERLOCUTOR INCIERTO","words":[["ego","ego","nominativo singular","yo"],["ecfodiebam","effodio","imperfecto indicativo primera singular, grafía arcaica","excavaba"],["in","in","preposición con ablativo","en"],["die","dies","ablativo singular","día"],["denos","deni","acusativo masculino plural distributivo","diez cada vez"],["scrobes","scrobis","acusativo masculino plural","hoyos"]],"section":"fragmenta"},{"n":"frg4","latin":"nec noctu nec diu quietus umquam eram, nunc dormiam.","spanish":"Ni de noche ni de día tenía nunca sosiego; ahora podré dormir.","speaker":"EUCLIÓN (atribución probable)","words":[["nec","nec","conjunción negativa","ni"],["noctu","noctu","ablativo temporal fosilizado","de noche"],["nec","nec","conjunción negativa","ni"],["diu","diu","adverbio temporal","de día"],["quietus","quietus","nominativo masculino singular","tranquilo"],["umquam","umquam","adverbio temporal","nunca"],["eram","sum","imperfecto indicativo primera singular","estaba"],["nunc","nunc","adverbio","ahora"],["dormiam","dormio","futuro indicativo primera singular","dormiré"]],"section":"fragmenta"},{"n":"frg5","latin":"qui mi holera cruda ponunt, hallec adduint.","spanish":"Que quienes me sirven verduras crudas añadan salsa de pescado.","speaker":"EUCLIÓN (atribución probable)","words":[["qui","qui","nominativo masculino plural relativo","quienes"],["mi","ego","dativo singular arcaico","me"],["holera","holus","acusativo neutro plural","verduras"],["cruda","crudus","acusativo neutro plural","crudas"],["ponunt","pono","presente indicativo tercera plural","sirven"],["hallec","hallec","acusativo neutro singular","salsa de pescado"],["adduint","addo","presente subjuntivo tercera plural arcaico","añadan"]],"section":"fragmenta"},{"n":"dub1","latin":"quin mi caperratam tuam frontem, Strobile, omittis?","spanish":"¿Por qué no dejas de fruncir el ceño, Estróbilo?","speaker":"LICÓNIDES (atribución conjetural)","words":[["quin","quin","partícula interrogativa exhortativa","por qué no"],["mi","ego","dativo singular arcaico","para mí"],["caperratam","caperratus","acusativo femenino singular","arrugada"],["tuam","tuus","acusativo femenino singular","tu"],["frontem","frons","acusativo femenino singular","frente"],["Strobile","Strobilus","vocativo masculino singular","Estróbilo"],["omittis","omitto","presente indicativo segunda singular","dejas"]],"section":"dubia"}]);

const notes = { ...prologueNotes,
 '229': {number:'229–235',type:'IMAGEN SOCIAL Y LENGUA',heading:'El buey y el asno: una alianza desigual',text:'Euclión presenta el matrimonio desigual como un yugo compartido por un buey y un asno (229–235). El doble rechazo —los asnos de su clase y los bueyes de la clase de Megadoro— dramatiza el temor a perder su lugar social. siem y fuat son subjuntivos arcaicos; locassim (228) admite análisis formal de futuro perfecto o perfecto subjuntivo. La interpretación social de esta escena se apoya en la oposición entre ricos y pobres que desarrolla el propio diálogo. Fuentes: F. Leo, Plauti Comoediae (1895), Aulularia II.2, vv. 225–235, edición digital https://beta.perseus.tufts.edu/urn:cts:latinLit:phi0119.phi003.perseus-lat2/ ; texto paralelo https://www.mqdq.it/testo/testo/codice/PLAVT%7Caulu%7C001 ; Matej Mlkvý, «Dos in the comedies of Plautus», Graeco-Latina Brunensia 30.2 (2025), pp. 47–70, https://doi.org/10.5817/GLB2025-2-3.'},
 '162': {number:'162–165',type:'LENGUA Y TRADICIÓN TEXTUAL',heading:'La edad y el nombre Póstumo',text:'El juego cómico vincula media aetas, una esposa ya madura y Postumus, nombre asociado también al nacimiento posterior a la muerte paterna. En 165 se mantiene demam, lectura transmitida por los manuscritos, frente a degam, variante atestiguada por Nonio y aceptada por algunos editores. El contraste demam et deminuam intensifica la negativa de Megadoro. Referencias: F. Leo, Plauti Comoediae (1895), Aul. 162–165; W. Stockert, T. Maccius Plautus. Aulularia (1983), aparato ad 165; Maclennan y Stockert, Plautus: Aulularia (2016), comentario ad 164–165. https://beta.perseus.tufts.edu/urn:cts:latinLit:phi0119.phi003.perseus-lat2/ ; https://dokumen.pub/plautus-aulularia-1910572373-9781910572375.html'},
 '713': {number:'713–716',type:'ESCENA Y LENGUA',heading:'El lamento ante los espectadores',text:'Euclión rompe la cuarta pared con preguntas directas al público: «quid ridetis?» seguirá en 717. La acumulación perii, interii, occidi dramatiza su desesperación; curram es subjuntivo deliberativo. En 714, quo eam / ubi sim / qui sim son interrogativas indirectas. En 715–716 la sintaxis de «mi auxilio, ... sitis» resulta elíptica y requiere colación crítica: se evita normalizarla sin respaldo. Fuente cotejada: Plauto, Aulularia IV.9, The Latin Library, https://www.thelatinlibrary.com/plautus/aulularia.shtml; edición base declarada Friedrich Leo (1895), cotejo directo pendiente.'},
 '701': {number:'701–704',type:'LÉXICO Y ESCENA',heading:'El esclavo se proclama rey',text:'Estróbilo se compara con Filipo, rey de Macedonia, famoso por su riqueza; la enumeración cómica degrada a los demás reyes a mendigos (mendicabula). La lectura Picis (701), vinculada por comentaristas con los grifos de las montañas auríferas, es problemática y queda pendiente de colación directa con Leo. Cotejo: The Latin Library, Aulularia IV.8, https://www.thelatinlibrary.com/plautus/aulularia.shtml; edición Leo (1895), https://scaife.perseus.org/library/urn:cts:latinLit:phi0119.phi003/.'},
 '696': {number:'696–700',type:'LENGUA Y ESCENA',heading:'La decisión como comicios',text:'La interrogativa indirecta ubi sit (697) lleva subjuntivo; irasci (699) es infinitivo deponente y rige dativo (illi). De capite meo sunt comitia (700) convierte una deliberación familiar en votación sobre la suerte de Licónides: caput puede referirse a la vida o a la condición jurídica de una persona. La lectura †Strobilum† aparece señalada como problemática en la tradición editorial y exige cotejo con el aparato crítico. Cotejo textual: Plauto, Aulularia IV.7, 696–700, https://www.mqdq.it/testo/testo/codice/PLAVT%7Caulu%7C001; edición base: F. Leo (1895), Perseus, https://beta.perseus.tufts.edu/urn:cts:latinLit:phi0119.phi003.perseus-lat2/ (colación directa pendiente).'},
 '691': {number:'691–695',type:'ESCENA Y RELIGIÓN',heading:'Juno Lucina y el parto',text:'Fedria se oye desde el interior, sin aparecer ante el público. La invocación Iuno Lucina, tuam fidem (692) recurre a Juno bajo su advocación protectora del alumbramiento; em (692) introduce la prueba inmediata que Licónides ofrece a Eunomia. Fuentes: Plauto, Aulularia IV.7, 691–695, The Latin Library, https://www.thelatinlibrary.com/plautus/aulularia.shtml; Friedrich Leo, Plauti Comoediae I (1895), testimonio digital Perseus, https://beta.perseus.tufts.edu/urn:cts:latinLit:phi0119.phi003.perseus-lat2/ (colación directa pendiente).'},
 '682': {number:'682–690',type:'LENGUA Y ESCENA',heading:'Petición y responsabilidad',text:'Licónides pide a Eunomia que interceda ante su tío Megadoro. Avonculus (685) designa al tío materno; compressisse (689) es un eufemismo latino de la violencia sexual, que no debe confundirse con consentimiento. Impetrassere (687) es forma arcaica de infinitivo perfecto; la grafía y su valor requieren cotejo directo con Leo (1895). Texto contrastado: Plauto, Aulularia IV.7, 682–690, https://www.thelatinlibrary.com/plautus/aulularia.shtml.'},
 '677': {number:'677–681',type:'LENGUA Y ESCENA',heading:'El provecho del riesgo',text:'Estróbilo se adelanta al bosque de Silvano para vigilar desde un árbol. En 679, ubi abstrudat es interrogativa indirecta con subjuntivo. En 681, malam rem quaerere alude al castigo que arriesga por el lucro; certum est expresa decisión. Fuente de cotejo: Plauto, Aulularia IV.6, 677–681, https://www.thelatinlibrary.com/plautus/aulularia.shtml. Pendiente colación directa con Leo (1895).'},
 '667': {number:'667–676',type:'LENGUA Y CULTURA',heading:'La Fidelidad traicionada',text:'Euclión contrapone a Fides, personificación de la confianza, con Silvano, divinidad asociada a los bosques: después del fracaso del templo, elige un bosque apartado (lucus, 674). Maxumam conserva la grafía arcaica del superlativo. Duim y perduim (672) son subjuntivos arcaicos de do y perdo; el paralelismo expresa su exagerada gratitud hacia el cuervo. El valor preciso de paenissume (668) requiere cotejo crítico adicional. Texto cotejado: Plauto, Aulularia IV.6, 667–676, https://latin.packhum.org/loc/119/3/23/66-68%2C94-96%2C487-489%403 y https://www.thelatinlibrary.com/plautus/aulularia.shtml; colación directa de Leo 1895 pendiente.'},
 '661': {number:'661–666',type:'LÉXICO Y DRAMATURGIA',heading:'La emboscada del esclavo',text:'El subjuntivo mavelim (661) expresa una preferencia extrema, seguida de quam y la cláusula negativa. En 665 foris es nominativo singular («la puerta»), no el adverbio homógrafo; foras al final sí indica movimiento hacia afuera. Ecferet/ecfert conservan la grafía arcaica con ec- frente a effero. Cotejo: Plauto, Aulularia IV.5, 661–666, https://www.thelatinlibrary.com/plautus/aulularia.shtml. La colación directa del aparato de Friedrich Leo (1895) permanece pendiente.'},
 '658': {number:'658–660',type:'ESCENA Y LENGUA',heading:'La despedida amenazante',text:'El deseo imprecatorio perdant (658) recibe la réplica irónica haud male egit gratias. En 660 fugin y abin contraen la partícula interrogativa -ne; cave ... videam se entiende como prohibición con ne elíptico. Socienno (659) designa al supuesto cómplice. Cotejo textual: Plauto, Aulularia IV.4, 658–660, https://www.thelatinlibrary.com/plautus/aulularia.shtml. Colación directa con Leo 1895 aún pendiente.'},
 '655': {number:'655–657',type:'DRAMATURGIA Y MORFOLOGÍA',heading:'Un cómplice imaginario',text:'La sospecha de un alter intus (655) enfrenta a Euclión con una decisión absurda: vigilar al esclavo ya registrado o perseguir a un cómplice supuesto. En 656 abierit se interpreta como futuro perfecto en la consecuencia de si amitto; su forma coincide con el perfecto de subjuntivo. En 657 perscrutavi, con terminación activa frente al paradigma deponente perscrutor, requiere cotejo textual directo con Leo. Fuentes de cotejo: https://www.thelatinlibrary.com/plautus/aulularia.shtml y https://is.muni.cz/el/phil/jaro2018/KLBcA20/um/Plautus_Aulularia.pdf.'},
 '651': {number:'651–654',type:'SINTAXIS Y ESCENA',heading:'El objeto que no se nombra',text:'Euclión exige la devolución de «id meum, quidquid habes» sin identificar el objeto: el temor de revelar su secreto prolonga el malentendido. En 653 perscrutatus es es perfecto deponente (perscrutor); en 654 penes rige el acusativo me, aunque aparece después del pronombre. Cotejo: Plauto, Aulularia IV.4, 651–654, https://www.thelatinlibrary.com/plautus/aulularia.shtml. Edición base atribuida a Friedrich Leo (1895), Perseus, https://beta.perseus.tufts.edu/urn:cts:latinLit:phi0119.phi003.perseus-lat2/; colación directa pendiente.'},
 '646': {number:'646–650',type:'LÉXICO Y ESCENA',heading:'El registro imposible',text:'La partícula -dum refuerza las órdenes agedum y excutedum; lubet conserva la vocal característica de una variante antigua de libet. La secuencia de manos y túnicas convierte la sospecha de Euclión en una inspección física cómica. Cotejo: Plauto, Aulularia IV.4, vv. 646–650, https://www.thelatinlibrary.com/plautus/aulularia.shtml; edición de Friedrich Leo (1895) identificada en https://catalog.perseus.org/catalog/urn:cts:latinLit:phi0119.phi003.perseus-lat1. Colación diplomática directa con Leo pendiente.'},
 '641': {number:'641–645',type:'HUMOR Y SINTAXIS',heading:'La tercera mano y el castigo',text:'Euclión exige una tercera mano imposible (641), prolongando la inspección del supuesto ladrón. En 643, maximam recupera iniuriam de la pregunta: la mayor injusticia, dice Euclión, es que el esclavo todavía no cuelgue de un suplicio. eccas (641) es forma presentativa de ecce con pronombre enclítico, no una forma regular de ecce; tui quicquam (645) combina genitivo partitivo y pronombre indefinido. Texto cotejado con Plauto, Aulularia IV.4, https://www.thelatinlibrary.com/plautus/aulularia.shtml (consulta 2026-11-16). Colación directa con Friedrich Leo (1895) pendiente.'},

 '633': {number:'633–640',type:'INSULTO Y JUEGO VERBAL',heading:'Del ladrón triple al equívoco de «poner»',text:'Euclión acumula verberabilissime (superlativo cómico, «merecedor de azotes») y trifur (fur intensificado). El intercambio pone / datare hace que Estróbilo transforme la orden «deja eso» en una réplica sobre lo que el viejo acostumbra a «dar». La fórmula sis equivale a si vis. Texto: Plauto, Aulularia IV.4, vv. 633–640, https://www.thelatinlibrary.com/plautus/aulularia.shtml; cotejo independiente del texto en https://is.muni.cz/el/phil/jaro2018/KLBcA20/um/Plautus_Aulularia.pdf (consulta 2026-11-16). Cotejo directo del aparato de Friedrich Leo (1895) pendiente.'},
 
 '628': {number:'628–632',type:'COMEDIA Y LÉXICO',heading:'La lombriz y el embaucador',text:'Euclión descubre al esclavo saliendo del santuario y lo llama lumbrice, «lombriz»: el vocativo animaliza a quien se ha ocultado bajo tierra. praestrigiator designa a un embaucador o ilusionista; el juego comparebas / compares / peris marca la súbita inversión de la suerte. En quid ... commerci (631), commerci es genitivo partitivo con quid. Fuente textual cotejada: Plauto, Aulularia IV.4, vv. 628–632, https://www.thelatinlibrary.com/plautus/aulularia.shtml (16-11-2026). Edición Friedrich Leo (1895), Perseus, pendiente de colación directa.'},
 '624': {number:'624–627',type:'AUSPICIOS Y TEATRO',heading:'El cuervo y el corazón acrobático',text:'Euclión interpreta el graznido del cuervo a su izquierda como presagio. El verbo onomatopéyico croccibat imita su voz; cor ... artem facere ludicram transforma el sobresalto en una imagen escénica de acrobacia. semul es grafía arcaica por simul. Texto contrastado: Plauto, Aulularia IV.3, vv. 624–627, https://www.thelatinlibrary.com/plautus/aulularia.shtml (16-11-2026). Cotejo directo con la edición de Friedrich Leo (1895) y análisis léxico de croccibat pendientes.'},
 '616': {number:'616–622',type:'LENGUA Y RELIGIÓN',heading:'Fides, fidelis y fidelia',text:'Estróbilo convierte la confianza religiosa de Euclión en una oportunidad de robo: exige que Fides sea fiel a él antes que al dueño. El eco Fides / fidelis / fidelia culmina en la promesa de una vasija de vino con miel que el esclavo piensa disfrutar. En 619 <virginis> es suplemento editorial; en 617 Fide exige cotejo crítico de la flexión del teónimo. Fuente de contraste: Plauto, Aulularia IV.2, vv. 616–622, https://www.thelatinlibrary.com/plautus/aulularia.shtml; base atribuida a Friedrich Leo (1895), Perseus Digital Library.'},
 '612': {number:'612–615',type:'RELIGIÓN Y LENGUA',heading:'La confianza en Fides',text:'Euclión se dispone a realizar un sacrificio y vuelve a pedir a Fides que custodie el oro. La construcción ne affinem morer quin (612–613) combina una finalidad negativa con quin; en tuae fide (615), fide puede reflejar una flexión arcaica o una construcción editorial discutida, que requiere cotejo directo con Leo. Fuente textual de contraste: Plauto, Aulularia IV.2, vv. 612–615, https://www.thelatinlibrary.com/plautus/aulularia.shtml; base: Friedrich Leo (1895), Perseus Digital Library.'},
 '608': {number:'608–611',type:'LENGUA Y RELIGIÓN',heading:'Fides y el secreto del oro',text:'Euclión se dirige a Fides como si la diosa pudiera divulgar su escondite. En 608 quoiquam es dativo arcaico (cuiquam) e indicassis forma sincopada de prohibición; en 610 ne es exclamativo, no negativo. Fuente: Plauto, Aulularia IV.2, vv. 608–611, cotejo con The Latin Library (https://www.thelatinlibrary.com/plautus/aulularia.shtml).'},
 
 '599': {number:'599–603',type:'LENGUA Y COMEDIA',heading:'Los ojos del esclavo y los grilletes',text:'Tras la laguna anterior, la máxima sobre el esclavo diligente continúa con frons / oculi: los ojos deben anticipar la voluntad expresada en el rostro del amo. Censione bubula (601) evoca humorísticamente el castigo con correas de cuero bovino; in splendorem compedes redigere (602) exagera el desgaste de los grilletes por el uso. La conexión sintáctica inicial de ediscat con el pasaje perdido no puede asegurarse. Cotejo: Plauto, Aulularia IV.1, vv. 599–603, https://www.thelatinlibrary.com/plautus/aulularia.shtml. Edición base: Friedrich Leo (1895), Perseus Digital Library; colación directa pendiente.'},

 '592': {number:'592–598',type:'CRÍTICA TEXTUAL Y SÍMIL',heading:'Una balsa para el enamorado',text:'La comparación del esclavo con una balsa de juncos (scirpea ratis) representa el deber de impedir que el amo se hunda en el amor. En la tradición textual, el pasaje 592–598 aparece entre corchetes y el verso 598 acaba con una laguna tras tamquam: no se reconstruye la comparación perdida. <eum> es suplemento editorial. La construcción de scirpea induitur ratis y la sintaxis de superare amorem requieren cotejo directo con el aparato de Leo. Fuente de cotejo: Plauto, Aulularia IV.1, https://www.thelatinlibrary.com/plautus/aulularia.shtml; edición de referencia Friedrich Leo, 1895, https://beta.perseus.tufts.edu/urn:cts:latinLit:phi0119.phi003.perseus-lat2/.'},
  '587': {number:'587–591',type:'LENGUA Y CARACTERIZACIÓN',heading:'El esclavo diligente',text:'Estróbilo presenta la prontitud ante las órdenes del amo como virtud servil. Servos (589) y servom (591) son grafías arcaicas por servus y servum; frugi (587) es indeclinable. El contraste matura / sera (590) opone las tareas urgentes del amo a las propias, postergables. Fuente: Plauto, Aulularia IV.1, vv. 587–591; F. Leo (1895), Perseus Digital Library, https://beta.perseus.tufts.edu/urn:cts:latinLit:phi0119.phi003.perseus-lat2/; cotejo https://www.thelatinlibrary.com/plautus/aulularia.shtml. La lectura de morae molestiaeque requiere cotejo adicional del aparato crítico.'},
 '584': {number:'580–586',type:'RELIGIÓN Y JUEGO VERBAL',heading:'La fidelidad de Fides',text:'Euclión traslada la olla al fanum de Fides, personificación romana de la buena fe y de la confianza. La invocación explota la repetición de Fides / fiducia y el temor de que la divinidad cambie de nombre (mutassis nomen) si falla como depositaria. En factu est optumum, factu es supino en -u de respecto; concreduo conserva una forma plautina de primera persona. Fuente textual: Plauto, Aulularia III.6, vv. 580–586, F. Leo (1895), Perseus https://beta.perseus.tufts.edu/urn:cts:latinLit:phi0119.phi003.perseus-lat2/; cotejo https://www.thelatinlibrary.com/plautus/aulularia.shtml.'},
 '578': {number:'575–579',type:'LENGUA Y ESCENA',heading:'La mudanza del tesoro y el baño ritual',text:'Euclión imagina que Megadoro quiere emborracharlo para llevarse el tesoro: commutet coloniam (576) trata el cambio de escondite como una mudanza de residencia. Faxo (578) es un futuro arcaico de facio; perdiderit puede describirse formalmente como futuro perfecto o perfecto de subjuntivo en la construcción dependiente. Lavatum (579) es supino de finalidad tras eo, y el baño prepara el sacrificio nupcial. Texto cotejado con Plauto, Aulularia III.6, vv. 575–579, The Latin Library, https://www.thelatinlibrary.com/plautus/aulularia.shtml. La colación directa con el aparato de Leo (1895) sigue pendiente.'},
 '571': {number:'567–574',type:'LENGUA',heading:'El vino y la amenaza velada',text:'El arcaísmo adferrier es un infinitivo presente pasivo en -ier, variante del clásico adferri. En el verso 567 caedundum conserva -und- por -end- del gerundivo. El adjetivo madidum significa literalmente «mojado», pero aplicado a la bebida anticipa la embriaguez que Euclión teme. Fuente textual de cotejo: Plauto, Aulularia III.6, vv. 567–574, The Latin Library, https://www.thelatinlibrary.com/plautus/aulularia.shtml; edición de referencia F. Leo, Plauti Comoediae I (1895), Perseus.'},
 '563': {number:'563–566',type:'LÉXICO',heading:'El cordero curio',text:'Euclión juega con curio y cura («preocupación»): cura macet. Curio era también el sacerdote encargado de una curia romana. La comparación con una lanterna Punica exagera la delgadez hasta hacer transparente al animal. Texto cotejado con Plauto, Aulularia III.6, vv. 561–566, https://www.thelatinlibrary.com/plautus/aulularia.shtml; cotejo directo con Leo (1895) pendiente.'},
 '556': {number:'555–559',type:'MITOLOGÍA Y SINTAXIS',heading:'Argos, Ío y la fuente Pirene',text:'Argos, guardián de Ío por orden de Juno, culmina la hipérbole de los cocineros: ni él podría controlarlos. La flautista introduce otra exageración: beberse la fuente Pirene de Corinto si estuviera llena de vino. Interbibere (558) depende de potest (559); su objeto es fontem Pirenam. Texto cotejado: Plauto, Aulularia III.6, vv. 555–559, https://www.thelatinlibrary.com/plautus/aulularia.shtml; F. Leo, ed. (1895), https://beta.perseus.tufts.edu/urn:cts:latinLit:phi0119.phi003.perseus-lat2/.'},
 '554': {number:'553–555',type:'MITOLOGÍA Y LENGUA',heading:'Gerión y Argos: demasiadas manos y ojos',text:'La hipérbole convierte a los cocineros en monstruos de seis manos: Gerión, tradicionalmente representado con tres cuerpos, aporta la imagen de una multiplicación de miembros; Argos, guardián de múltiples ojos, anticipa el verso siguiente. Senis es distributivo (seis por persona), no genitivo de senex. Texto de cotejo: Friedrich Leo, ed., Plauti Comoediae (1895), Aulularia III.6, vv. 553–556, https://beta.perseus.tufts.edu/urn:cts:latinLit:phi0119.phi003.perseus-lat2/; lectura comparada: https://www.thelatinlibrary.com/plautus/aulularia.shtml.'},
 '547': {number:'547–550',type:'LECTURA Y LENGUA',heading:'«Lo que ahora tienes»: un equívoco',text:'La fórmula amistosa de Megadoro (quod nunc habes) alarma a Euclión, que la interpreta como prueba de que conoce su tesoro. La imagen del senado en v. 549 convierte cómicamente el aparte del viejo en una deliberación política. Texto: Plauto, Aulularia III.6, vv. 545–550; cotejo abierto: The Latin Library, https://www.thelatinlibrary.com/plautus/aulularia.shtml. Las palabras entre ángulos son suplementos editoriales y no se presentan como transmisión segura.'},
 '534': {number:'534–535',type:'CONTEXTO CULTURAL',heading:'La dote y la autoridad marital',text:'Megadoro opone la mujer sin dote, que a su juicio queda bajo la potestas del marido, a la mujer dotada, capaz de arruinarlo con sus exigencias. Es una caricatura masculina de la dote, no una descripción neutral del matrimonio romano. Fuente: Plauto, Aulularia III.5, vv. 531–536, https://www.thelatinlibrary.com/plautus/aulularia.shtml.'},
 '525': {number:'525–531',type:'CONTEXTO CULTURAL',heading:'La dote y el banquero',text:'La enumeración pasa de los artesanos a la liquidación de cuentas: incluso después de pagar a los proveedores, el soldado reclama su dinero. Argentarius designa al profesional que lleva o ajusta las cuentas; la secuencia dramatiza la insolvencia del marido que financia el lujo asociado a la dote. El texto latino se cotejó con The Latin Library, Aulularia III.5, vv. 521–530, https://www.thelatinlibrary.com/plautus/aulularia.shtml.'},
 '511': {number:'511–520',type:'CRÍTICA TEXTUAL',heading:'Un catálogo de transmisión problemática',text:'En la edición de Friedrich Leo (1895), vv. 511–520, aparecen timorobatharii, semisonarii, phylacistae, limbolarii y acularii; otras ediciones presentan murobatharii, sonarii o zonarii, thylacistae, limbularii y arcularii. No se debe tratar estas equivalencias como seguras. El verso 515 es objeto de discusión editorial. Fuente: Leo, Comoediae I, p. 140 y aparato, https://resources.warburg.sas.ac.uk/pdf/eph720b2450290.pdf; Jan Radicke, análisis del catálogo 505–535, https://journals.ub.uni-heidelberg.de/index.php/gfa/article/download/93457/88162.'},
 '505': {number:'505–510',type:'HISTORIA Y CRÍTICA TEXTUAL',heading:'El desfile de los oficios',text:'El catálogo caricaturiza la economía del vestido y los gastos matrimoniales. Algunos nombres de oficio son raros o discutidos; las equivalencias españolas son aproximadas. El v. 508 transmite phyrgio, frente a la forma esperable phrygio. Para las variantes y la hipótesis de versiones superpuestas, véase Jan Radicke, estudio sobre Aulularia 505–535, Göttinger Forum für Altertumswissenschaft, https://journals.ub.uni-heidelberg.de/index.php/gfa/article/download/93457/88162; cotejo: Friedrich Leo, Comoediae (1895), III.5, vv. 505–510, https://upload.wikimedia.org/wikipedia/commons/0/07/Comoediae%3B_%28IA_comoedia01plau%29.pdf.'},

 '503': {number:'503',type:'CRÍTICA TEXTUAL',heading:'Euclión y la vigilancia de las costumbres',text:'Euclión aprueba irónicamente que Megadoro sea nombrado guardián de las costumbres femeninas. Los vv. 503–504 se han considerado posiblemente interpolados: O. Zwierlein, Zur Kritik und Exegese des Plautus IV: Bacchides (1992), p. 225 n. 508, citado y discutido en Jan Radicke, Roman Women’s Dress, cap. 5.2, «The catalogue of the dealers (505–535)», https://uplopen.com/books/5343/files/60bd5754-614c-4a10-8447-fa195e91327a.pdf. Texto de cotejo: Simon Laursen, Aulularia (2013), p. 17, https://klassisk.ribekatedralskole.dk/personer/plautus/Aulularia4.pdf. La atribución a Plauto es debatida, no se suprime el pasaje.',source:'Laursen (2013), p. 17; Radicke, cap. 5.2; Zwierlein (1992), p. 225 n. 508 (referencia indirecta).'},
 '489': {number:'489',type:'LENGUA',heading:'El objetor imaginario',text:'Qui dicat introduce a un interlocutor hipotético, con subjuntivo de caracterización; la pregunta quo illae nubent presupone el valor social de la dote. En la réplica, dum ... ne fiat formula una condición restrictiva.',source:'Plauto, Aulularia III.5, 489–491; Friedrich Leo, Plauti Comoediae I (1895), edición base Perseus https://beta.perseus.tufts.edu/urn:cts:latinLit:phi0119.phi003.perseus-lat2/; cotejo The Latin Library https://www.thelatinlibrary.com/plautus/aulularia.shtml.'},
 '494': {number:'494',type:'LENGUA',heading:'Mulas y caballos',text:'Faxim es una forma arcaica del perfecto de subjuntivo de facio, aquí con valor potencial; cantheriis es ablativo de comparación con viliores. La comparación con los jamelgos galos convierte el lujo matrimonial en un contraste de precios deliberadamente cómico.',source:'Plauto, Aulularia III.5, 492–495; Friedrich Leo (1895), Perseus https://beta.perseus.tufts.edu/urn:cts:latinLit:phi0119.phi003.perseus-lat2/; The Latin Library https://www.thelatinlibrary.com/plautus/aulularia.shtml.'},
 '488': {number:'488',type:'LENGUA',heading:'Ni ley ni zapatero',text:'La coordinación neque lex neque sutor enfrenta la autoridad normativa y el oficio que trabaja con medidas. La construcción est qui possit presenta una relativa de característica con subjuntivo; capere modum significa poner límite. La ironía reside en la imposibilidad de moderar la codicia.',source:'Plauto, Aulularia III.5, 485–488; F. Leo, Plauti Comoediae I (1895), https://www.lateinlex.de/?call=Puc&permalink=Plaut_Aul; cotejo textual The Latin Library, https://www.thelatinlibrary.com/plautus/aulularia.shtml.'},
 '481': {number:'481',type:'LENGUA',heading:'La condición y sus consecuencias',text:'La prótasis si idem faciant (478) abre una propuesta hipotética que desemboca en subjuntivos: ducant, fiat, utamur, metuant y simus. El subjuntivo expresa aquí una posibilidad imaginada, no una disposición legal. Multo es ablativo de diferencia con concordior.',source:'Plauto, Aulularia III.5, 478–484; F. Leo, Plauti Comoediae I (1895), texto digital Perseus https://beta.perseus.tufts.edu/urn:cts:latinLit:phi0119.phi003.perseus-lat2/; cotejo The Latin Library https://www.thelatinlibrary.com/plautus/aulularia.shtml.'},
 '483': {number:'483',type:'LENGUA',heading:'Metuont: forma arcaica',text:'Metuont corresponde a metuunt en la flexión clásica, presente de indicativo activo, tercera persona plural. La contraposición metuant / metuont distingue lo que las mujeres harían en la situación imaginada y lo que hacen actualmente. La secuencia quam ... magis es comparativa.',source:'Plauto, Aulularia III.5, 483; The Latin Library https://www.thelatinlibrary.com/plautus/aulularia.shtml; Leo (1895), Perseus https://beta.perseus.tufts.edu/urn:cts:latinLit:phi0119.phi003.perseus-lat2/.'},

 '475': {number:'475',type:'CONTEXTO',heading:'Un programa matrimonial',text:'Megadoro presenta el matrimonio sin dote como una propuesta de alcance colectivo, pero su discurso posterior satiriza a las esposas dotadas. La interpretación no debe confundir la opinión del personaje con una norma jurídica vigente.',source:'F. Leo, Plauti Comoediae I (1895), Aulularia 475–490, https://www.lateinlex.de/?call=Puc&permalink=Plaut_Aul; Jan Radicke, Roman Women’s Dress, cap. 5, pp. 88 ss., https://uplopen.com/books/5343/files/065e036b-ee06-4d8c-bb25-8952c3eea951.pdf'},
 '478': {number:'478',type:'LENGUA',heading:'Una condición que continúa',text:'La prótasis si idem faciant (478) continúa en los versos siguientes: no debe leerse como una oración completa. Opulentiores especifica ceteri y pauperiorum filias anticipa el verbo ducant (480).',source:'Plauto, Aulularia III.5, 478–480, ed. F. Leo (1895); https://www.lateinlex.de/?call=Puc&permalink=Plaut_Aul'},
 '471': {number:'471',type:'TEXTO',heading:'Una dificultad de transmisión',text:'La marca editorial ~ ante manubrium señala un problema textual; no representa una palabra latina. El juego entre ex manu y manubrium enlaza el supuesto soborno del gallo con el botín. El verso 472 se presenta entre corchetes en la transcripción cotejada y no debe confundirse con texto indiscutido.',source:'Plauto, Aulularia III.4, 470–472, transcripción The Latin Library: https://www.thelatinlibrary.com/plautus/aulularia.shtml; cotejo del aparato de Leo pendiente.'},
 '474': {number:'474',type:'LENGUA',heading:'Ausim y conloquar',text:'Ausim es forma potencial arcaica de audeo, históricamente perfecto de subjuntivo; conloquar es presente de subjuntivo deponente. El cambio de escena se produce después de este verso, al entrar Megadoro.',source:'Plauto, Aulularia III.4, 473–474; The Latin Library: https://www.thelatinlibrary.com/plautus/aulularia.shtml.'},
 '465': {number:'465',type:'LENGUA',heading:'El gallo y la ironía',text:'Condigne es una valoración irónica: Euclión atribuye al gallo una conspiración contra su olla. Med conserva la -d final arcaica del acusativo pronominal. En paenissume (466) hay una forma intensiva de interpretación delicada; no equivale sin más a un superlativo clásico regular.',source:'F. Leo, Plauti Comoediae I (1895), Aulularia 465–466; https://www.lateinlex.de/?call=Puc&permalink=Plaut_Aul'},
 '469': {number:'469',type:'LENGUA',heading:'Un ladrón sorprendido',text:'Manufestarium es grafía arcaizante vinculada a manifestus, aplicado al ladrón sorprendido en el acto. El presente histórico capio / obtrunco acelera la acción. El testimonio de The Latin Library presenta cirum circa en 468, mientras otros textos imprimen circum circa: se adopta la segunda segmentación y se deja pendiente el cotejo del aparato crítico.',source:'F. Leo, Plauti Comoediae I (1895), Aulularia 467–469; https://www.thelatinlibrary.com/plautus/aulularia.shtml; https://klassisk.ribekatedralskole.dk/personer/plautus/Aulularia4.pdf'},
 '461': {number:'461',type:'LENGUA',heading:'El pobre frente al rico',text:'El relativo qui se refiere al pauper que inicia tratos con el opulento homine: la inversión social y el temor a perder la olla sostienen la sospecha de Euclión. Rem habere aut negotium es una acumulación de términos próximos.',source:'F. Leo, Plauti Comoediae I (1895), Aulularia 460–461; https://www.lateinlex.de/?call=Puc&permalink=Plaut_Aul'},
 '464': {number:'464',type:'LENGUA',heading:'Qui con valor final',text:'En hoc qui surriperent, qui introduce una finalidad con imperfecto de subjuntivo, equivalente en el contexto a ut. La interpretación es sintáctica y no convierte el relativo ordinario en regla universal.',source:'F. Leo, Plauti Comoediae I (1895), Aulularia 464; https://www.thelatinlibrary.com/plautus/aulularia.shtml'},
 '456': {number:'456',type:'CULTURA',heading:'La paga por recibir golpes',text:'Congrión convierte la violencia del amo en una reclamación salarial: pro vapulando expresa el motivo de la paga. El contraste de supinos coctum / vapulatum (457) opone la finalidad del contrato a los golpes efectivamente recibidos. La figura del cocinero apaleado es un motivo cómico documentado.',source:'F. Leo, Plauti Comoediae I (1895), Aulularia 456–457; Università di Ferrara, «Il cuoco vapulatus, una figura della commedia», https://www.unife.it/stum/lettere/insegnamenti/lingua-e-letteratura-latina-ii/materiale-didattico-1/materiale-didattico-2021-2022/handout-complessivo-del-corso/at_download/file'},
 '459': {number:'459',type:'LENGUA',heading:'Abi: la réplica como espejo',text:'La escena termina con una repetición invertida del imperativo abi: Euclión expulsa al cocinero y Congrión devuelve la orden mediante tu enfático. In malum cruciatum es una imprecación de dirección figurada; malum concuerda con cruciatum, ambos masculinos acusativos.',source:'Friedrich Leo, Plauti Comoediae I (1895), Aulularia 459; https://www.thelatinlibrary.com/plautus/aulularia.shtml'},
 '458': {number:'458',type:'LENGUA',heading:'Lege agito mecum',text:'La réplica de Euclión adopta el lenguaje del litigio: «procede judicialmente contra mí». Agito es imperativo futuro de ago, formalmente idéntico al presente indicativo de agito; el contexto exhortativo favorece la lectura imperativa. Lege es ablativo de norma.',source:'F. Leo, Plauti Comoediae I (1895), Aulularia 458; texto cotejado con https://www.thelatinlibrary.com/plautus/aulularia.shtml'},

 '445': {number:'445',type:'CULTURA',heading:'Laverna y el juramento del cocinero',text:'Congrión invoca a Laverna, divinidad asociada en las fuentes romanas al mundo del engaño y del hurto. El juramento intensifica la protesta del cocinero maltratado. <uti> se conserva como suplemento editorial visible, no como texto seguro de la transmisión.',source:'F. Leo, Plauti Comoediae I (1895), Aulularia III.2, 445; texto comparado: https://www.thelatinlibrary.com/plautus/aulularia.shtml'},
 '446': {number:'446',type:'LÉXICO',heading:'Pipulo differam',text:'Pipulo (ablativo de medio) señala una denuncia a gritos delante de la casa; differam, literalmente «difundiré», funciona aquí como amenaza de escándalo público. En el verso 448 mercedest contrae mercede est, construcción con opus est.',source:'F. Leo, Plauti Comoediae I (1895), Aulularia III.2, 446–448; cotejo: https://www.thelatinlibrary.com/plautus/aulularia.shtml'},

 '439': {number:'439',type:'SINTAXIS',heading:'Condición contraria a los hechos',text:'Si adesses (439) y auferres (440) son imperfectos de subjuntivo de una condición irreal: Euclión imagina que el cocinero se hubiera quedado en el fogón y no habría sufrido el golpe. Fissile concuerda con caput; la imagen concreta del cráneo partido intensifica la amenaza cómica.',source:'F. Leo, Plauti Comoediae I (1895), Aulularia III.2, 439–440; cotejo: https://www.thelatinlibrary.com/plautus/aulularia.shtml'},
 '442': {number:'442',type:'MORFOLOGÍA',heading:'Dos futuros perfectos',text:'Accesseris e iussero se interpretan como futuros perfectos de indicativo en una amenaza proyectada hacia el futuro. Sus formas coinciden con las del perfecto de subjuntivo, de modo que la identificación depende de la construcción condicional y del contexto.',source:'F. Leo, Plauti Comoediae I (1895), Aulularia III.2, 442–443; https://www.thelatinlibrary.com/plautus/aulularia.shtml'},
 '431': {number:'431',type:'SINTAXIS',heading:'Preguntas en espejo',text:'Sinas an non sinas: interrogativa indirecta disyuntiva, con subjuntivo. Euclión repite volo scire, pero desplaza la pregunta de la cena a sus bienes. Texto: F. Leo (1895), https://beta.perseus.tufts.edu/urn:cts:latinLit:phi0119.phi003.perseus-lat2/; cotejo https://www.thelatinlibrary.com/plautus/aulularia.shtml.'},
 '432': {number:'432',type:'LENGUA',heading:'Domi y mean',text:'Domi es locativo de domus; mean representa mea más -n interrogativa. Salva futura [esse] concuerda con los bienes en neutro plural. Contexto escénico: Plautus: Aulularia (2016), https://dokumen.pub/plautus-aulularia-1910572373-9781910572375.html; texto base Leo (1895).'},
 '427': {number:'427',type:'SINTAXIS',heading:'¿Qué asunto tenías en mi casa?',text:'Quid ... negoti es una construcción con genitivo partitivo; me absente (428) forma un ablativo absoluto. El intercambio hace que la sospecha de Euclión choque con la respuesta práctica del cocinero. Texto: F. Leo, Plauti Comoediae I (1895), https://beta.perseus.tufts.edu/urn:cts:latinLit:phi0119.phi003.perseus-lat2/; cotejo https://www.thelatinlibrary.com/plautus/aulularia.shtml.'},
 '429': {number:'429',type:'MORFOLOGÍA',heading:'Dos formas de coctum',text:'Coctum (429) es supino de finalidad con venimus; coctum (430) es participio perfecto pasivo sustantivado, opuesto a crudum. La oposición produce la réplica absurda de Euclión. Mi (430) es dativo arcaico de ego. Texto: F. Leo (1895), https://beta.perseus.tufts.edu/urn:cts:latinLit:phi0119.phi003.perseus-lat2/; cotejo https://www.thelatinlibrary.com/plautus/aulularia.shtml.'},
 '420': {number:'420',type:'LENGUA',heading:'Amenaza y respuesta irónica',text:'Quoi es dativo arcaico de qui; faxim es una forma antigua del subjuntivo perfecto de facio, aquí potencial. Congrión responde con testist (testis est) y la comparación hiperbólica con cinaedus, palabra de connotación peyorativa antigua que exige cautela en español. Cotejo textual: Friedrich Leo, Plauti Comoediae (1895), https://beta.perseus.tufts.edu/urn:cts:latinLit:phi0119.phi003.perseus-lat2/; https://www.thelatinlibrary.com/plautus/aulularia.shtml.'},
 '417': {number:'417',type:'LENGUA Y ESCENA',heading:'El cuchillo del cocinero',text:'El culter, instrumento profesional del cocus, se interpreta como arma. Comminatu\'s contrae comminatus es (perfecto deponente); tris (416) y tuom conservan grafías arcaicas. Cotejo: F. Leo, Plauti Comoediae I (1895), reproducido en https://www.lateinlex.de/?call=Puc&permalink=Plaut_Aul_III_II; https://www.thelatinlibrary.com/plautus/aulularia.shtml.'},
 '411a': {number:'411a',type:'FILÓLOGÍA',heading:'Bacchanal y la numeración subdividida',text:'Congrión llama Bacchanal a la casa de Euclión, prolongando la imagen de las bacantes del v. 408. Los segmentos 411a y 412a conservan la subdivisión editorial del verso. Ipsus (412a) es forma antigua de ipse; omnis (414) es acusativo plural por omnes. Cotejo: Friedrich Leo, Plauti Comoediae I (1895), https://www.lateinlex.de/?call=Puc&permalink=Plaut_Aul; texto: https://www.documentacatholicaomnia.eu/03d/-250_-150%2C_Plautus._Titus_Maccius%2C_Aulularia%2C_LT.pdf.'},
 '410': {number:410,type:'ESCENA Y LENGUAJE',heading:'Bacanal y gimnasio de golpes',text:'Congrión compara la casa de Euclión con un Bacchanal (408), lugar de furor báquico, y transforma el castigo físico en un gymnasium (410), imagen cómica de entrenamiento. Coquinatum (408) es supino de finalidad. El comienzo Optati vires (406) presenta una dificultad de interpretación textual: se conserva la lectura del texto cotejado sin disimularla. Base: F. Leo, Plauti Comoediae I (1895), https://www.lateinlex.de/?call=Puc&permalink=Plaut_Aul; cotejo: https://www.thelatinlibrary.com/plautus/aulularia.shtml.'},
 '405': {number:405,type:'LÉXICO Y COMICIDAD',heading:'La cocina y el tumulto',text:'Exdorsua (399) es un imperativo técnico de exdorsuo, «quitar el espinazo»; artopta (400) designa un recipiente para cocer u hornear. En 402, volsus ludiust equivale a volsus ludius est, comparación burlesca con un actor depilado; suom (404) es grafía arcaica del posesivo suum y fuat (405) es subjuntivo antiguo de sum. El contraste entre el trabajo culinario y los gritos de la casa vecina prolonga el equívoco dramático. Texto: Plauto, Aulularia II.9, 398–405, Friedrich Leo, Plauti Comoediae I (1895), https://www.lateinlex.de/?call=Puc&permalink=Plaut_Aul; cotejo independiente: https://www.thelatinlibrary.com/plautus/aulularia.shtml y https://www.intratext.com/IXT/LAT0549/_PF.HTM.'},
  '397': {number:397,type:'CRÍTICA TEXTUAL Y RELIGIÓN',heading:'Apolo y la transmisión del verso 393',text:'La línea 393 aparece entre corchetes en la transcripción de The Latin Library: su autenticidad es discutida y aquí se presenta expresamente como texto editorialmente cuestionado, no como verso seguro de Plauto. En 396, <si> indica suplemento editorial. Mi (394) es dativo arcaico; antidhac (396), adverbio temporal antiguo. Apolo es invocado como arquero capaz de castigar a los supuestos ladrones. Fuente de cotejo: https://www.thelatinlibrary.com/plautus/aulularia.shtml; edición de referencia: F. Leo, Plauti Comoediae I (1895), https://beta.perseus.tufts.edu/urn:cts:latinLit:phi0119.phi003.perseus-lat2/.'},
 '392': {number:392,type:'EQUÍVOCO Y MORFOLOGÍA',heading:'Dos ollas, dos significados',text:'Congrión pide una olla mayor para cocinar (aula, vv. 390–391); Euclión oye una alusión a su olla con oro y cree que se la están buscando (aula quaeritur, v. 392). Quit es presente de queo, verbo defectivo; si pote es una expresión elíptica. Cotejo: Plauto, Aulularia II.8, 390–392, Friedrich Leo (1895), https://www.lateinlex.de/?call=Puc%26permalink=Plaut_Aul; The Latin Library, https://www.thelatinlibrary.com/plautus/aulularia.shtml.'},
 '389': {number:389,type:'RELIGIÓN Y LENGUA',heading:'Del pequeño sacrificio al pánico',text:'Tusculum (385) es diminutivo de tus: Euclión reduce al mínimo incluso su ofrenda. El Lar (386) es la divinidad doméstica invocada junto al hogar. Gnatae (387) conserva una grafía arcaica de natae; aedis (388) es acusativo plural en -is. Strepitust (389) contrae strepitus est y compilor es pasivo de compilo, «ser saqueado». Texto cotejado: Plauto, Aulularia II.8, 385–389, https://www.thelatinlibrary.com/plautus/aulularia.shtml. Edición base: Friedrich Leo, Plauti Comoediae I (1895), https://scaife.perseus.org/library/urn:cts:latinLit:phi0119.phi003/.'},
 '384': {number:384,type:'SINTAXIS Y COSTUMBRES',heading:'Economía doméstica y bodas',text:'La oposición festo die / profesto (380–381) convierte el ahorro en máxima proverbial. Prodegeris y peperceris pueden leerse como futuros perfectos en la condición; liceat es subjuntivo potencial. Ventri cordique (382) personifica el cuerpo y la deliberación. Quam minimo sumptu (384) significa «con el menor gasto posible»; nuptum es supino de nubo en la locución nuptum dare. Cotejo textual: Plauto, Aulularia II.8, 380–384, https://www.thelatinlibrary.com/plautus/aulularia.shtml. Referencia editorial: Friedrich Leo, Plauti Comoediae I (1895), https://www.lateinlex.de/?call=Puc%26permalink=Plaut_Aul.'},
 '379': {number:379,type:'LÉXICO Y MORFOLOGÍA',heading:'Pensar por el camino',text:'Egomet refuerza el pronombre ego mediante -met; mecum conserva cum pospuesto al pronombre; intervias es un adverbio arcaico de recorrido. La construcción cogitare occepi se completa en el verso 380. En el verso 377, qui emam admite explicación como relativo con matiz instrumental o potencial: se conserva la incertidumbre. Cotejo: Plauto, Aulularia II.8, 376–379, https://www.thelatinlibrary.com/plautus/aulularia.shtml; referencia editorial Friedrich Leo (1895), https://beta.perseus.tufts.edu/urn:cts:latinLit:phi0119.phi003.perseus-lat2/.'},
 '375': {number:375,type:'LÉXICO Y RETÓRICA',heading:'Carestía y enumeración',text:'La repetición de carus en caros, caram y cara convierte el catálogo de carnes y pescados en una queja cómica. Filiai (v. 372) es genitivo singular arcaico en -ai; macellum designa el mercado de alimentos. Plauto, Aulularia II.8, 371–375; cotejo: https://www.thelatinlibrary.com/plautus/aulularia.shtml; edición de referencia: Friedrich Leo (1895), https://beta.perseus.tufts.edu/urn:cts:latinLit:phi0119.phi003.perseus-lat2/.'},
 '370': {number:370,type:'LÉXICO Y SINTAXIS',heading:'Rapacidae y la vigilancia',text:'Rapacidarum es genitivo plural de una formación expresiva rapacida, vinculada con rapax: Pitódico califica a los cocineros de ladrones voraces. Nil negoti (v. 369) es genitivo partitivo y siet conserva la terminación arcaica del subjuntivo sit. Texto cotejado: Plauto, Aulularia II.7, 369–370, https://www.thelatinlibrary.com/plautus/aulularia.shtml; edición de referencia F. Leo (1895), https://beta.perseus.tufts.edu/urn:cts:latinLit:phi0119.phi003.perseus-lat2/.'},
 '368': {number:368,type:'JUEGO VERBAL',heading:'Los de arriba y los de abajo',text:'Superi e inferi designan aquí a quienes permanecen arriba o abajo del pozo, pero evocan también a los dioses celestes e infernales. La oposición incenati/cenati remata el chiste. Plauto, Aulularia II.7, 363–368; Friedrich Leo (1895), https://www.lateinlex.de/?call=Puc&permalink=Plaut_Aul; cotejo https://www.thelatinlibrary.com/plautus/aulularia.shtml. Sobre el juego de palabras, Studies in the Word-Play in Plautus, p. 109, https://upload.wikimedia.org/wikipedia/commons/5/59/Studies_in_the_word-play_in_Plautus_%28IA_cu31924026478325%29.pdf.'},

 '358': {number:358,type:'LÉXICO Y CULTURA MATERIAL',heading:'Los tablones como leña',text:'Asseres son tablas o vigas de madera, no combustible preparado: Congrión transforma el material de construcción en ligna. El equívoco provoca la acusación de querer incendiar la casa. Plauto, Aulularia II.6, 357–361; texto cotejado con https://www.thelatinlibrary.com/plautus/aulularia.shtml; edición base Friedrich Leo (1895), https://scaife.perseus.org/library/urn:cts:latinLit:phi0119.phi003/.'},
 '359': {number:359,type:'RELIGIÓN Y HUMOR',heading:'Vulcano y el incendio',text:'Volcano es dativo regido por studes: la alusión a Vulcano, dios del fuego, convierte el oficio del cocinero en una devoción peligrosa. La acusación se prolonga hasta el verso 361. Plauto, Aulularia II.6, 359–361; cotejo https://www.thelatinlibrary.com/plautus/aulularia.shtml.'},

 '354': {number:354,type:'RELIGIÓN Y LÉXICO',heading:'¿Boda para Ceres?',text:'Cererin contrae Cererem y la partícula interrogativa -ne; la mención de Ceres prepara el chiste sobre la ausencia de vino. Véase Plauto, Aulularia II.6, 354–355; F. Leo, Plauti Comoediae (1895), https://beta.perseus.tufts.edu/urn:cts:latinLit:phi0119.phi003.perseus-lat2/; cotejo https://www.thelatinlibrary.com/plautus/aulularia.shtml.'},
 '355': {number:355,type:'SINTAXIS',heading:'Temeti nihil',text:'Temeti es genitivo partitivo de temetum (vino), dependiente de nihil. La réplica explica la alusión a Ceres mediante la falta de bebida en el banquete. Texto: Plauto, Aulularia II.6, 355; cotejo https://www.thelatinlibrary.com/plautus/aulularia.shtml.'},
 '347': {number:347,type:'HUMOR Y VIOLENCIA ESCÉNICA',heading:'El pozo como castigo',text:'La sucesión de imperativos comprehendite, vincite, verberate, condite acelera la amenaza contra los cocineros. La imagen del pozo exagera cómicamente la sospecha de robo. Plauto, Aulularia II.5, 346–347; Friedrich Leo, Plauti Comoediae (1895), https://www.lateinlex.de/?call=Puc&permalink=Plaut_Aul; cotejo https://www.thelatinlibrary.com/plautus/aulularia.shtml.'},
 '349': {number:349,type:'MORFOLOGÍA',heading:'Sequere y sequor',text:'Sequere es imperativo presente singular del deponente sequor, mientras que sequor es indicativo presente en primera persona. Subripias, subjuntivo presente, expresa una posibilidad caracterizadora. La respuesta breve cierra la escena. Plauto, Aulularia II.5, 348–349; texto de Leo (1895) en https://www.lateinlex.de/?call=Puc&permalink=Plaut_Aul.'},
 '343': {number:343,type:'CULTURA MATERIAL',heading:'La riqueza de una casa romana',text:'Supellex es el ajuar o mobiliario doméstico; familia puede designar el conjunto de esclavos y servidores, no solo el parentesco. El inventario (aurum, vestis, vasa argentea) prepara la acusación preventiva contra los cocineros. Texto: Plauto, Aulularia II.5, 342–346; F. Leo, Plauti Comoediae (1895), https://beta.perseus.tufts.edu/urn:cts:latinLit:phi0119.phi003.perseus-lat2/; cotejo: https://www.thelatinlibrary.com/plautus/aulularia.shtml.'},
 '345': {number:345,type:'SINTAXIS Y HUMOR',heading:'Una honradez condicionada',text:'Scio te ... posse construye acusativo con infinitivo. La salvedad si nihil obviam est convierte la aparente confianza en Congrión en una acusación velada: solo se abstiene cuando no encuentra nada que llevarse. Perierit en la prótasis se interpreta como futuro perfecto, aunque coincide formalmente con el perfecto de subjuntivo. Plauto, Aulularia II.5, 344–345; cotejo: https://www.thelatinlibrary.com/plautus/aulularia.shtml.'},
 '332': {number:332,type:'HUMOR ESCÉNICO',heading:'Del cordero a la flautista',text:'La respuesta de Pitódico cambia el objeto de comparación: pinguior se aplicaba al cordero (331), pero ahora califica a tibicina (332). El adjetivo permite trasladar el agravio del reparto de carne al cuerpo de una intérprete musical. Texto: Plauto, Aulularia II.5, 331–333; Friedrich Leo (1895), https://www.lateinlex.de/?call=Puc&permalink=Plaut_Aul; cotejo: https://www.thelatinlibrary.com/plautus/aulularia.shtml.'},
 '335': {number:335,type:'MORFOLOGÍA Y ESCENA',heading:'Hucine detrusti?',text:'Hucine une el adverbio direccional huc con la partícula interrogativa enclítica -ne. Detrusti es perfecto de detrudo; la forma breve contrasta con detrusisti. Congrión entiende el destino de la casa de Euclión como una trampa por su proverbial tacañería. Plauto, Aulularia II.5, 334–335; cotejo textual: https://www.thelatinlibrary.com/plautus/aulularia.shtml.'},
 '324': {number:324,type:'CALENDARIO Y HUMOR',heading:'El cocinero de las nundinae',text:'Nundinalest contrae nundinalis est. Las nundinae eran jornadas periódicas de mercado en un ciclo de ocho días transcurridos, denominado noveno por cómputo inclusivo. Ántrax ridiculiza a Congrión como cocinero ocasional. Plauto, Aulularia II.4, 324–325; cotejo textual: https://www.thelatinlibrary.com/plautus/aulularia.shtml.'},
 '325': {number:325,type:'JUEGO VERBAL',heading:'Tres letras: fur',text:'Tr ium litterarum homo alude a FVR (fur, «ladrón»), tres letras en escritura latina. Congrión lanza el insulto y Ántrax lo amplifica con trifurcifer, término injurioso intensivo. Plauto, Aulularia II.4, 325–326; https://www.thelatinlibrary.com/plautus/aulularia.shtml.'},
 '316': {number:316,type:'GRAFÍAS ARCAICAS',heading:'Milvos y milvom',text:'Las formas milvos (nominativo) y milvom (acusativo) conservan grafías antiguas frente a milvus y milvum. La escena lleva la avaricia al absurdo jurídico: Euclión quiere citar ante el pretor a un milano. Plauto, Aulularia 316–319; Friedrich Leo, Plauti Comoediae I (1895), https://beta.perseus.tufts.edu/urn:cts:latinLit:phi0119.phi003.perseus-lat2/; cotejo https://www.thelatinlibrary.com/plautus/aulularia.shtml.'},
 '319': {number:319,type:'MORFOLOGÍA Y DERECHO',heading:'El infinitivo vadarier',text:'Vadarier es infinitivo presente deponente arcaico en -ier, equivalente formal de vadari, del verbo jurídico vador: exigir comparecencia mediante caución. El absurdo es intentar someter a ese procedimiento a un ave. Texto: Plauto, Aulularia 319; https://www.thelatinlibrary.com/plautus/aulularia.shtml.'},
 '311': {number:311,type:'HIPÉRBOLE',heading:'Prestar hambre',text:'Famem utendam imagina el hambre como objeto prestado; utendam es gerundivo femenino acusativo de utor. Texto cotejado: Plauto, Aulularia II.4, v. 311, https://www.thelatinlibrary.com/plautus/aulularia.shtml.'},
 '312': {number:312,type:'MORFOLOGÍA',heading:'Unguis y praesegmina',text:'Unguis es acusativo plural con -is antiguo por -es. Praesegmina designa los recortes de uñas, que el avaro se lleva. Texto cotejado: Plauto, Aulularia II.4, vv. 312–313, https://www.thelatinlibrary.com/plautus/aulularia.shtml.'},

 '304': {number:304,type:'DOBLE SENTIDO',heading:'La garganta inferior',text:'Ántrax transforma la imagen del fuelle en una alusión escatológica: inferiorem gutturem se refiere eufemísticamente al ano. La réplica mantiene la fórmula ne quid animae amittat del verso anterior, pero con animai, genitivo singular arcaico. Cotejo: Plauto, Aulularia II.4, vv. 303–305, https://www.thelatinlibrary.com/plautus/aulularia.shtml.'},
 '309': {number:309,type:'LÉXICO Y SOCIEDAD',heading:'Un talento para la libertad',text:'Ántrax pregunta si se podría obtener de Euclión un talentum magnum para hacerse libres. El talento es una unidad monetaria de gran valor; la broma depende de la imposibilidad de conseguir tal suma de un avaro. La secuencia qui fiamus liberi emplea qui con valor final arcaico. Cotejo: Plauto, Aulularia II.4, vv. 309–310, https://www.thelatinlibrary.com/plautus/aulularia.shtml.'},
 '298': {number:298,type:'TRANSMISIÓN TEXTUAL',heading:'Laguna después del verso 298',text:'Después de tute existuma, el testimonio digital consultado señala una interrupción con asteriscos (298a) antes de suam rem periisse (299). Se conserva el salto y no se reconstruye la sintaxis perdida. Cotejo: Plauto, Aulularia II.4, https://www.thelatinlibrary.com/plautus/aulularia.shtml; edición base: Friedrich Leo (1895), https://scaife.perseus.org/library/urn:cts:latinLit:phi0119.phi003/.'},
 '302': {number:302,type:'HIPÉRBOLE CÓMICA',heading:'El aliento que no debe escaparse',text:'La tacañería se extiende hasta el aire: follem obstringit ob gulam y ne quid animae amittat exageran el miedo de perder incluso el aliento. Dormitum es supino de finalidad tras it; eradicarier (299) conserva el infinitivo pasivo arcaico en -ier. Texto: Plauto, Aulularia II.4, vv. 299–303, https://www.thelatinlibrary.com/plautus/aulularia.shtml.'},

 '295': {number:295,type:'MORFOLOGÍA',heading:'Filiai y obsonari',text:'Filiai es genitivo singular antiguo de filia; obsonari es infinitivo presente deponente («comprar provisiones»). Cotejo: Plauto, Aulularia II.4, vv. 293–297, https://www.thelatinlibrary.com/plautus/aulularia.shtml; Friedrich Leo (ed.), Plauti Comoediae I (1895), https://scaife.perseus.org/library/urn:cts:latinLit:phi0119.phi003/.'},
 '297': {number:297,type:'IMAGEN CÓMICA',heading:'La sequedad de la piedra pómez',text:'Pumex («piedra pómez») ofrece una comparación hiperbólica para la tacañería de Euclión. Non aeque ... atque niega la igualdad: el viejo es todavía más «seco». Texto: Plauto, Aulularia II.4, v. 297, https://www.thelatinlibrary.com/plautus/aulularia.shtml.'},
 '285': {number:285,type:'IRONÍA ESCÉNICA',heading:'Un prostituto muy recatado',text:'Congrión responde a Ántrax con un oxímoron burlón: pudicum prostibulum. Popli es forma sincopada de populi. Cotejo: Plauto, Aulularia II.4, vv. 285–286; Friedrich Leo (ed.), Plauti Comoediae I, Berlín, 1895, https://scaife.perseus.org/library/urn:cts:latinLit:phi0119.phi003/; https://www.thelatinlibrary.com/plautus/aulularia.shtml.'},
 '287': {number:287,type:'LENGUA Y DIÁLOGO',heading:'Alio vorsum',text:'Pitódico corrige el equívoco: la división se refería a las provisiones. Alio vorsum equivale a «en otro sentido»; vorsum conserva grafía arcaizante. La lectura de quo en el verso siguiente merece cotejo sintáctico adicional con comentario especializado. Texto: Plauto, Aulularia II.4, vv. 287–289, Friedrich Leo (1895), Perseus; cotejo https://www.thelatinlibrary.com/plautus/aulularia.shtml.'},
 '281': {number:281,type:'MORFOLOGÍA',heading:'Tibicinasque y hasce',text:'Tibicinasque reúne tibicinas y la enclítica copulativa -que. Hasce es un demostrativo reforzado por -ce; ambas formas designan a las flautistas presentes en escena. Texto: Plauto, Aulularia II.4, vv. 280–282, F. Leo (ed.), Plauti Comoediae I (1895), Perseus Digital Library, https://scaife.perseus.org/library/urn:cts:latinLit:phi0119.phi003/; cotejo https://www.thelatinlibrary.com/plautus/aulularia.shtml.'},
 '283': {number:283,type:'JUEGO VERBAL',heading:'Dividir las provisiones, no al cocinero',text:'Ántrax interpreta literalmente divides, que Pitódico aplicaba a la distribución de los alimentos, y finge temer que lo partan a él. Tibi aparece entre corchetes angulares en la transcripción cotejada, como suplemento editorial, no como palabra segura de la tradición. Plauto, Aulularia II.4, vv. 282–284; https://www.thelatinlibrary.com/plautus/aulularia.shtml; edición de referencia Friedrich Leo (1895).'},
 '276': {number:276,type:'DRAMATURGIA',heading:'El secreto y el parto',text:'Probrum designa la deshonra social vinculada aquí al embarazo que el público conoce desde el prólogo; partitudo es un nombre poco común para el parto. La coordinación concentra el temor de Estáfila ante la inminente boda. Referencias: Plauto, Aulularia II.3, vv. 275–279, Friedrich Leo (ed.), Plauti Comoediae I (Berlín, 1895), edición digital Perseus https://beta.perseus.tufts.edu/urn:cts:latinLit:phi0119.phi003.perseus-lat2/; cotejo https://www.thelatinlibrary.com/plautus/aulularia.shtml.'},
 '278': {number:278,type:'MORFOLOGÍA',heading:'Sient y el temor final',text:'Sient es variante arcaica del subjuntivo sint, de sum. En el verso siguiente metuo ne bibam presenta una subordinada de temor: ne no equivale aquí a una negación simple. La imagen de beber un mal mezclado con tristeza prolonga la angustia de Estáfila. Referencia: Plauto, Aulularia II.3, vv. 278–279; Friedrich Leo (1895), texto digital Perseus https://beta.perseus.tufts.edu/urn:cts:latinLit:phi0119.phi003.perseus-lat2/.'},
 '272': {number:272,type:'DRAMATURGIA',heading:'Una boda demasiado repentina',text:'El optativo di bene vortant expresa un deseo favorable, pero la objeción subitum est nimis anticipa el peligro que Estáfila conoce: el embarazo de la hija, anunciado ya en el prólogo (vv. 28–30) y recordado en I.1 (vv. 74–75). Plauto, Aulularia 272; texto cotejado con The Latin Library, https://www.thelatinlibrary.com/plautus/aulularia.shtml; edición base Friedrich Leo, Plauti Comoediae I (1895).'},
 '273': {number:273,type:'SINTAXIS',heading:'Curata fac sint',text:'Fac introduce una completiva volitiva con sint, mientras curata funciona como predicativo neutro plural de los preparativos sobreentendidos. Cum a foro redeam presenta una subordinada temporal orientada al regreso futuro. Plauto, Aulularia 273; cotejo textual The Latin Library, https://www.thelatinlibrary.com/plautus/aulularia.shtml.'},
 '268': {number:268,type:'LÉXICO',heading:'Deblateravisti',text:'Deblaterare es un verbo expresivo y despectivo, propio del registro cómico: Euclión acusa a Estáfila de divulgar indiscretamente la noticia. La acusación no prueba que ella lo haya hecho. Plauto, Aulularia 268–269; texto cotejado con https://www.thelatinlibrary.com/plautus/aulularia.shtml.'},
 '271': {number:271,type:'SINTAXIS',heading:'Nuptum dabo',text:'Nuptum es supino de nubo, con valor final en la fórmula de dar a la hija en matrimonio; despondi remite al compromiso recién acordado. El dativo huic Megadoro identifica al futuro esposo. Plauto, Aulularia 271; cotejo https://www.thelatinlibrary.com/plautus/aulularia.shtml.'},
 '266': {number:266,type:'CRÍTICA TEXTUAL',heading:'Verso entre corchetes',text:'La línea 266 se transmite aquí entre corchetes en la transcripción de The Latin Library: es una señal editorial de sospecha textual, no un parlamento seguro sin reservas. Se reproduce la marca sin suprimirla ni decidir su autenticidad; cotejo directo del aparato de Friedrich Leo (1895) pendiente. Texto de contraste: https://www.thelatinlibrary.com/plautus/aulularia.shtml.'},
 '267': {number:267,type:'LÉXICO',heading:'Inhiat y ea gratia',text:'Inhiat expresa el deseo ávido de Euclión atribuido a Megadoro; ea gratia significa «por ese motivo». La acusación pertenece al punto de vista del avaro, no a una comprobación del narrador. Plauto, Aulularia 267; cotejo: https://www.thelatinlibrary.com/plautus/aulularia.shtml.'},

 '262': {number:262,type:'SINTAXIS',heading:'Num quae causa est quin…?',text:'La interrogación num quae causa est quin faciamus hodie? plantea una posible objeción para rechazarla; quin introduce aquí subjuntivo presente (faciamus). Immo edepol optuma es una réplica elíptica de Euclión, que califica de excelente la propuesta. Cotejo textual: Plauto, Aulularia 261–262, The Latin Library, https://www.thelatinlibrary.com/plautus/aulularia.shtml; edición de referencia F. Leo, Plauti Comoediae I (1895), Perseus Digital Library.'},
 '264': {number:264,type:'CULTURA MATERIAL',heading:'Macellum',text:'Macellum designa el mercado de comestibles al que Megadoro envía a su criado para preparar el banquete nupcial. El imperativo sequere es deponente (sequor) y no una forma pasiva de significado pasivo. Texto: Plauto, Aulularia 264, cotejo https://www.thelatinlibrary.com/plautus/aulularia.shtml; referencia textual F. Leo (1895).'},
 '165': {number:165,type:'LÉXICO Y ESTILO',heading:'Demam et deminuam: dos futuros',text:'Megadoro promete a su hermana que le quitará la preocupación de buscarle esposa. Demam (demo) y deminuam (deminuo) son aquí futuros de primera persona singular; las formas también admiten, aisladamente, lectura de subjuntivo presente. La repetición del prefijo de- intensifica la promesa. Cotejo: Plauto, Aulularia 165, F. Leo, Plauti Comoediae I (1895), https://www.lateinlex.de/?call=Puc&permalink=Plaut_Aul; https://www.thelatinlibrary.com/plautus/aulularia.shtml.'},
 '166': {number:166,type:'MORFOLOGÍA',heading:'Deum y maiorum nostrum',text:'Deum es genitivo plural de deus, forma antigua por deorum. En virtute deum et maiorum nostrum, ambos genitivos dependen de virtute: Megadoro atribuye su riqueza a la virtud o favor de los dioses y de los antepasados. Nostrum se interpreta aquí como forma posesiva de genitivo plural junto a maiorum; no es el pronombre partitivo nostrum. Cotejo textual: Plauto, Aulularia 166, https://www.thelatinlibrary.com/plautus/aulularia.shtml; texto base: F. Leo (1895), Perseus Digital Library.'},
 '164': {number:164,type:'JUEGO VERBAL',heading:'Postumus: un nombre inoportuno',text:'Megadoro imagina que, si un anciano deja embarazada a una mujer de edad avanzada, el hijo recibirá el nombre Postumus. La broma juega con el valor temporal del nombre, asociado en latín al hijo nacido después de la muerte del padre, y con la avanzada edad del supuesto progenitor; no debe confundirse esta asociación con una explicación segura de todas las prácticas onomásticas romanas. Texto: Plauto, Aulularia 162–164, cotejo https://www.thelatinlibrary.com/plautus/aulularia.shtml; edición de referencia F. Leo (1895), https://beta.perseus.tufts.edu/urn:cts:latinLit:phi0119.phi003.perseus-lat2/.'},
 '201': {number:201,type:'LÉXICO',heading:'Harpagatum est',text:'Harpagatum est es perfecto pasivo de harpago, verbo expresivo de robo o rapiña; la acusación nace del temor de Euclión, no de una constatación. Texto: Plauto, Aulularia 201, ed. F. Leo (1895), https://www.lateinlex.de/?call=Puc&permalink=Plaut_Aul; cotejo https://www.thelatinlibrary.com/plautus/aulularia.shtml.'},
 '205': {number:205,type:'MORFOLOGÍA',heading:'Rebitur y el futuro de reor',text:'Rebitur es futuro de indicativo del deponente reor (pensar, suponer). El giro sese a me derideri contiene acusativo e infinitivo pasivo. Fuente textual: Plauto, Aulularia 204–206, ed. F. Leo (1895), https://www.lateinlex.de/?call=Puc&permalink=Plaut_Aul; cotejo https://www.thelatinlibrary.com/plautus/aulularia.shtml.'},
 '62': {number:61,type:'MORFOLOGÍA',heading:'Verba dare y el arcaísmo duit',text:'En ne mi ex insidiis verba imprudenti duit (v. 62), verba dare es una locución idiomática para «engañar»; duit es subjuntivo presente arcaico de do, en la subordinada de temor dependiente de metuo (v. 61). La coordinación neu persentiscat mantiene el mismo marco sintáctico. Fuente: Plauto, Aulularia I.1, 60–64, ed. Friedrich Leo, Plauti Comoediae I (1895), https://beta.perseus.tufts.edu/urn:cts:latinLit:phi0119.phi003.perseus-lat2:1.1/; cotejo https://www.lateinlex.de/?call=Puc&permalink=Plaut_Aul.'},
 '50': {number:59,type:'MORFOLOGÍA',heading:'Adaxint: deseo y forma arcaica',text:'En utinam me divi adaxint (vv. 50–51), adaxint expresa un deseo con perfecto de subjuntivo; la forma arcaica en -int corresponde al paradigma de adigo. El sentido de la frase es una preferencia desesperada de Estáfila por morir antes que seguir sirviendo así. Fuente textual: Plauto, Aulularia 50–51, ed. Friedrich Leo, Plauti Comoediae I (1895), https://beta.perseus.tufts.edu/urn:cts:latinLit:phi0119.phi003.perseus-lat2/; cotejo https://www.thelatinlibrary.com/plautus/aulularia.shtml.'},
 '53': {number:60,type:'MORFOLOGÍA',heading:'Ecfodiam y quid rerum',text:'Ecfodiam (v. 53) es formalmente ambiguo entre futuro de indicativo y presente de subjuntivo; la amenaza directa favorece el futuro. En quid rerum geram (v. 54), rerum es genitivo partitivo con quid y geram es subjuntivo de interrogativa indirecta. Fuente textual: Plauto, Aulularia 53–54, ed. Leo (1895), https://beta.perseus.tufts.edu/urn:cts:latinLit:phi0119.phi003.perseus-lat2/; cotejo https://www.thelatinlibrary.com/plautus/aulularia.shtml.'},
 '56': {number:61,type:'MORFOLOGÍA',heading:'Astato e istoc: orden y deixis',text:'Astato es imperativo futuro de asto (adsto), no presente de indicativo. Istoc es ablativo masculino de iste con refuerzo deíctico -c y concuerda con loco. La orden delimita el lugar del que Estáfila no debe moverse. Fuente: Plauto, Aulularia 56, ed. Friedrich Leo, Plauti Comoediae I (Berlín, 1895), https://www.lateinlex.de/?call=Puc&permalink=Plaut_Aul; cotejo textual https://www.thelatinlibrary.com/plautus/aulularia.shtml.'},
 '58': {number:62,type:'SINTAXIS Y HUMOR',heading:'Respexis y la aprendiz de la cruz',text:'Respexis (v. 58) es forma sincopada por respexeris, interpretada como futuro perfecto en la condición; la morfología también permite perfecto de subjuntivo. Donicum significa «hasta que»; con la negación implícita de la prohibición se entiende «antes de que te lo ordene». Discipulam cruci (v. 59) convierte la amenaza de crucifixión en una grotesca imagen de aprendizaje. Fuente textual: Plauto, Aulularia 57–59, ed. Friedrich Leo (1895), https://www.lateinlex.de/?call=Puc&permalink=Plaut_Aul; referencia general de comentario: Joanne Walker, A Commentary on Plautus’ Aulularia (tesis, St Andrews, 2005), https://research-repository.st-andrews.ac.uk/handle/10023/14536. La lectura del chiste es observación editorial, no cita de Walker.'},
 '191': {number:57,type:'LÉXICO SOCIAL',heading:'Dote cassam e inlocabilem',text:'La falta de dote se presenta como impedimento para casar a la hija. Cassam rige ablativo de privación (dote); inlocabilem remite a locare en el sentido matrimonial. Texto: Plauto, Aulularia II.2, vv. 191–192, ed. Friedrich Leo, Plauti Comoediae I (Berlín, Weidmann, 1895), pp. 89–126, https://scaife.perseus.org/library/urn:cts:latinLit:phi0119.phi003/; cotejo https://www.thelatinlibrary.com/plautus/aulularia.shtml.'},
 '195': {number:58,type:'IMAGEN CÓMICA',heading:'La piedra y el pan',text:'Euclión contrapone lo que Megadoro muestra (pan) y lo que oculta (piedra): la promesa amable encubriría un daño. Es una interpretación del personaje, no una prueba de la intención de Megadoro. Véase Plauto, Aulularia II.2, vv. 194–195, ed. Leo (1895), https://scaife.perseus.org/library/urn:cts:latinLit:phi0119.phi003/; texto paralelo https://www.thelatinlibrary.com/plautus/aulularia.shtml.'},
 '188': {number:55,type:'SINTAXIS',heading:'Qui ... colas',text:'El relativo qui introduce una construcción de finalidad o posibilidad con subjuntivo: «con que puedas llevar una buena vida». Véase Plauto, Aulularia 188, ed. Friedrich Leo (1895), Perseus Digital Library, https://beta.perseus.tufts.edu/urn:cts:latinLit:phi0119.phi003.perseus-lat2/; cotejo The Latin Library, https://www.thelatinlibrary.com/plautus/aulularia.shtml.'},
 '190': {number:56,type:'LENGUA COLOQUIAL',heading:'Loquere y el aparte',text:'Loquere conserva una desinencia arcaica de segunda persona singular deponente, equivalente a loqueris. Megadoro oye el aparte de Euclión sin comprender su causa. Texto comparado con Plauto, Aulularia II.2, ed. Leo (1895), Perseus; The Latin Library, https://www.thelatinlibrary.com/plautus/aulularia.shtml.'},
 '181': {number:53,type:'ESTILO',heading:'Properare propero',text:'La repetición del infinitivo y del verbo conjugado intensifica cómicamente la prisa de Euclión. Egomet refuerza el contraste entre el cuerpo que está aquí y el ánimo que ya está en casa.'},
 '183': {number:54,type:'MORFOLOGÍA',heading:'Recten y sies',text:'Recten contiene la enclítica interrogativa -ne; sies es variante arcaica del subjuntivo sis, empleada en un deseo de buena fortuna.'},
 '177': {number:51,type:'FILOLÓGICA',heading:'Eccum y video',text:'Eccum contrae ecce eum. Los corchetes angulares de <video> indican suplemento editorial, no palabra transmitida con certeza.'},
 '176': {number:52,type:'MORFOLOGÍA',heading:'Conveniam y domi',text:'Conveniam es aquí futuro de convenio, aunque coincide formalmente con el subjuntivo presente; domi es locativo sin preposición.'},
 '171': {number:49,type:'MORFOLOGÍA',heading:'Nostin',text:'Nostin contrae novistine, perfecto de nosco con enclítica interrogativa -ne; el perfecto tiene aquí sentido de presente: «¿conoces?».'},
 '174': {number:50,type:'SINTAXIS',heading:'Dictura es',text:'La perífrasis de participio futuro dictura es anticipa la objeción de Eunomia. Haec pauper placet insiste en la pobreza como cualidad deseada, no como impedimento.'},
 '164': {number:47,type:'JUEGO VERBAL',heading:'Postumus',text:'El nombre Postumus sugiere al hijo nacido después de la muerte del padre, pero también evoca lo tardío de una paternidad a edad avanzada. La broma juega con ambas asociaciones.'},
 '168': {number:48,type:'CULTURA MATERIAL',heading:'Vehicla y púrpura',text:'Vehicla es forma sincopada de vehicula. Los carruajes adornados con marfil y la vestimenta teñida de púrpura forman parte de una enumeración satírica del lujo matrimonial.'},
 '155': {number:45,type:'CULTURA',heading:'Foras feratur',text:'La expresión alude al traslado del cadáver fuera de casa para las exequias: Megadoro solo aceptaría una esposa que muriese inmediatamente después de casarse.'},
 '158': {number:46,type:'MORFOLOGÍA',heading:'Grandior natu',text:'Natu es supino en -u empleado como ablativo de respecto con el comparativo grandior: mayor en edad.'},
 '148': {number:43,type:'MORFOLOGÍA',heading:'Faxint',text:'Faxint es una forma optativa arcaica de facio, generalmente analizada como subjuntivo perfecto; la fórmula invoca el favor de los dioses.'},
 '152': {number:44,type:'LENGUA COLOQUIAL',heading:'Face y lubeat',text:'Face conserva una variante antigua del imperativo fac; lubeat presenta la vocal arcaica u frente a libeat. La respuesta de Megadoro introduce una reserva burlona.'},
 '144': {number:41,type:'MORFOLOGÍA',heading:'Monitum advento',text:'El supino en -um (monitum) indica finalidad con el verbo de movimiento advento; ted conserva el acusativo arcaico de segunda persona.'},
 '142': {number:42,type:'PRAGMÁTICA',heading:'Amabo y tuast',text:'Amabo funciona como fórmula coloquial de cortesía, no como declaración amorosa. Tuast representa la contracción de tua est.'},
  '136': {number:39,type:'PRAGMÁTICA',heading:'Una cortesía desmontada',text:'Eunomia obliga a Megadoro a precisar su elogio; él lo retira en cuanto ella lo rechaza. El intercambio prepara el tópico misógino de los versos siguientes.'},
  '140': {number:40,type:'MORFOLOGÍA',heading:'Alia alia peior',text:'La primera alia es nominativo (una mujer); la segunda, ablativo de comparación (que otra). La identidad gráfica sostiene la concisión del chiste.'},
  '127': {number:37,type:'MORFOLOGÍA',heading:'Cogitato',text:'Imperativo futuro de cogito, aquí una exhortación solemne. El acusativo arcaico ted aparece en el v. 133.'},
  '132': {number:38,type:'SINTAXIS',heading:'Consejo recíproco',text:'La acumulación de infinitivos y la construcción quin… ut facias resultan sintácticamente densas. Se traduce el sentido recíproco sin fingir una correspondencia palabra por palabra inequívoca.'},
  '120': {number:35,type:'MORFOLOGÍA',heading:'Med, meai y tuai',text:'Med es acusativo arcaico de ego; meai y tuai son genitivos femeninos antiguos. Se conservan estas grafías plautinas y se omiten únicamente marcas prosódicas.'},
  '123': {number:36,type:'SINTAXIS',heading:'Haud falsa sum',text:'La forma falsa, participio o adjetivo, adquiere aquí sentido activo: «no estoy equivocada». La generalización sobre las mujeres es una broma del personaje, no una afirmación editorial.'},
  '117': {number:33,type:'ESTILO',heading:'Rogitant y la cortesía sospechosa',text:'Rogitant es un frecuentativo de rogo: la repetición de preguntas cotidianas se vuelve sospechosa para Euclión. Las tres interrogativas indirectas llevan subjuntivo.'},
  '119': {number:34,type:'SINTAXIS',heading:'Quantum… tantum',text:'La correlación quantum potero tantum intensifica la urgencia del regreso. Me recipiam es futuro en el contexto, aunque su forma coincide con el presente de subjuntivo.'},
  '111': {number:31,type:'SINTAXIS',heading:'Veri simile y parvi facere',text:'Veri simile expresa verosimilitud; parvi facere, «estimar en poco». Quin con subjuntivo depende de la negación previa.'},
  '113': {number:32,type:'GRAFÍA',heading:'Omnis y omnes',text:'Omnis (v. 113) es acusativo plural arcaico, mientras que omnes (vv. 114–115) es nominativo plural. La forma escrita permite distinguir sus funciones.'},
  '101': {number:28,type:'IRONÍA',heading:'La Buena Fortuna no se acerca',text:'Estáfila invierte la prohibición de Euclión: la Fortuna misma evita la casa. Pol es una fórmula de juramento por Pólux, frecuente en el diálogo cómico.'},
  '105': {number:29,type:'MORFOLOGÍA',heading:'Discrucior animi',text:'Discrucior es pasivo de discrucio con sentido reflexivo («me atormento»); animi es genitivo de relación. Abeundum est mihi expresa obligación impersonal con dativo de agente.'},
  '107': {number:30,type:'INSTITUCIONES',heading:'Magister curiae',text:'El magister curiae preside una de las curias cívicas. La distribución de monedas por cabeza explica la salida de Euclión: teme que negarse a una suma pequeña delate su riqueza oculta.'},
  '91': {number:25,type:'SINTAXIS',heading:'Quod quispiam',text:'Quod introduce aquí una hipótesis práctica: si alguien viene a pedir una brasa. El subjuntivo quaerat expresa eventualidad. Leo (1895), Aulularia I.2, v. 91.'},
  '93': {number:26,type:'JUEGO VERBAL',heading:'El fuego vivo y la esclava apagada',text:'Vivet se aplica al fuego y extinguere amenaza a Estáfila: Euclión juega con el mismo campo léxico. Extinguere es futuro pasivo de segunda persona, variante de extingueris, no un imperativo.'},
  '100': {number:27,type:'CULTURAL',heading:'Bona Fortuna',text:'La Buena Fortuna aparece personificada como visitante. Euclión lleva su obsesión al extremo: prefiere mantener la puerta cerrada incluso a la prosperidad.'},
  '79': {number:22,type:'LÉXICA',heading:'Defaecato animo',text:'Defaecare significa aclarar un líquido por decantación. El ablativo absoluto defaecato animo convierte la comprobación del tesoro en una purificación mental: Euclión sale aliviado solo después de inspeccionar su escondite.'},
  '82': {number:23,type:'RETÓRICA',heading:'¿Llevarse la casa?',text:'Estáfila responde con ironía a la orden de vigilar una casa supuestamente vacía: ¿habría que impedir que los ladrones se lleven incluso el edificio? El contraste entre pobreza aparente y oro oculto sostiene el diálogo.'},
  '86': {number:24,type:'CULTURAL',heading:'Filipo y Darío',text:'Filipo de Macedonia y Darío de Persia funcionan como emblemas de riqueza regia. Euclión convierte la mención de telarañas en un ataque desproporcionado contra Estáfila; trivenefica intensifica el insulto.'},

  '75': {number: 20,type:'LÉXICA',heading:'Partitudo',text:'Partitudo designa el parto o alumbramiento. La proximidad del nacimiento explica la urgencia de Estáfila por ocultar la situación de la hija de Euclión.'},
  '78': {number: 21,type:'RETÓRICA',heading:'Una letra larga',text:'El giro ex me unam faciam litteram longam transforma la imagen del ahorcamiento en una figura gráfica: el cuerpo suspendido se imagina como una letra alargada, tradicionalmente interpretada como una I. La comicidad verbal convive con la desesperación de Estáfila. Leo (1895) imprime meum sin corchetes; otras transcripciones lo marcan como suplemento.'},
  '67': {number: 18,type:'LINGÜÍSTICA',heading:'Noenum y mecastor',text:'Noenum es una negación antigua y mecastor un juramento por Cástor. Estáfila expresa su desconcierto mediante una interrogativa deliberativa.'},
  '73': {number: 19,type:'CULTURAL',heading:'Como un zapatero cojo',text:'La comparación con un zapatero cojo ridiculiza la inmovilidad de Euclión: permanece sentado en casa, aunque expulsa continuamente a Estáfila.'},
  '62': { number: 11, type: 'LINGÜÍSTICA', heading: 'Verba dare · duit', text: 'Verba dare alicui es una expresión idiomática: «engañar a alguien». Duit es una forma arcaica del presente de subjuntivo de do, no un indicativo. Fuente: Plauto, Aulularia I.1, v. 62, ed. Leo (1895).' },
  '64': { number: 12, type: 'RETÓRICA', heading: 'Ojos en la nuca', text: 'La hipérbole de los ojos en el occipitium convierte la vigilancia de Estáfila en una amenaza imaginaria para Euclión. Pessima, nominativo femenino, es una caracterización insultante de la esclava. Fuente: Leo (1895), v. 64.' },
  '65': { number: 13, type: 'MORFOLÓGICA', heading: 'Sitne · visam', text: 'Sitne contiene la enclítica interrogativa -ne, en una interrogativa indirecta dependiente de visam. Visam es subjuntivo presente de viso, verbo frecuentativo de video; no es futuro de video. Fuente: Leo (1895), v. 65.' },
  '55': { number: 8, type: 'RETÓRICA', heading: 'Una orden que se estira', text: 'La repetición de etiam nunc, seguida del abrupto ohe, convierte la vigilancia obsesiva de Euclión en una secuencia de gestos escénicos. Texto base: Leo (1895), Aulularia I.1, vv. 55–56.' },
  '57': { number: 9, type: 'LINGÜÍSTICA', heading: 'Digitum transvorsum', text: 'La expresión mide una distancia mínima: ni un dedo de lado ni el ancho de una uña. Transvorsum conserva una variante gráfica antigua de transversum. Fuente: Leo (1895), Aulularia I.1, v. 57.' },
  '59': { number: 10, type: 'CULTURAL', heading: 'Discipulam cruci', text: 'La amenaza de entregar a Estáfila como «alumna» a la cruz es una personificación cruel del suplicio: la cruz aparece como maestra de castigo. No debe perderse el doble sentido de discipulam. Fuente: Leo (1895), Aulularia I.1, v. 59.' },
  '40': { number: 1, type: 'FILOLÓGICA', heading: 'Exi · exeundum', text: 'La insistencia en exi y la variación exi / exeundum producen una apertura entrecortada y agresiva. Hercle, invocación a Hércules, es una fórmula corriente de juramento en la comedia.' },
  '41': { number: 2, type: 'LÉXICA', heading: 'Una fisgona con ojos de explorador', text: 'Circumspectatrix es una formación excepcional de Plauto para quien mira a todas partes. Emissicius evoca a quien se envía a reconocer o explorar: los ojos de Estáfila parecen espías que buscan el secreto de Euclión.' },
  '43': { number: 3, type: 'FILOLÓGICA', heading: 'Mala malam', text: 'La yuxtaposición de mala (vocativo) y malam (acusativo) refuerza el insulto por repetición de la raíz. El juego sonoro importa tanto como el significado.' },
  '45': { number: 4, type: 'CULTURAL', heading: 'Stimulorum seges', text: 'Literalmente, «cosecha de aguijones». El cuerpo de la esclava se convierte metafóricamente en un campo donde proliferan los instrumentos de castigo. La exageración cómica no elimina la violencia de la relación entre amo y esclava.' },
  '46': { number: 5, type: 'LINGÜÍSTICA', heading: 'Illuc sis vide', text: 'Aquí sis funciona como una fórmula coloquial de cortesía, contraída de si vis («si quieres»). No debe confundirse con el subjuntivo sis de sum, que aparece unos versos antes.' },
  '49': { number: 6, type: 'FILOLÓGICA', heading: 'Grandibo gradum', text: 'La proximidad sonora entre grandibo y gradum es una paronomasia. Grandio, «hacer mayor», es un verbo muy raro. La imagen del paso de tortuga convierte una amenaza de golpes en un chiste cruel sobre la lentitud de Estáfila.' },
  '50': { number: 7, type: 'MORFOLÓGICA', heading: 'Adaxint', text: 'Adaxint equivale a adegerint: es una forma arcaica del perfecto de subjuntivo de adigo. Su empleo tras utinam expresa un deseo, formulado aquí con deliberada exageración dramática.' }
};

notes['449'] = {number:'449',type:'DRAMATURGIA',heading:'La olla sale de la casa',text:'Hoc e id remiten al recipiente con el tesoro. El deíctico y la repetición mecum convierten la desconfianza de Euclión en acción escénica: a partir de ahora lleva la olla consigo.',source:'Plauto, Aulularia III.3, 449–450; F. Leo, Plauti Comoediae I (1895), texto digital en Perseus: https://beta.perseus.tufts.edu/urn:cts:latinLit:phi0119.phi003.perseus-lat2/; cotejo: https://www.thelatinlibrary.com/plautus/aulularia.shtml'};
notes['452'] = {number:'452',type:'LÉXICO',heading:'Grex venalium',text:'Grex venalium designa un conjunto de personas puestas en venta, aquí esclavos; venalium es genitivo plural sustantivado. Euclión exagera con sarcasmo: después de expulsar a los cocineros, permite hasta la entrada de una multitud.',source:'Plauto, Aulularia III.3, 451–453; F. Leo (1895); cotejo: https://www.thelatinlibrary.com/plautus/aulularia.shtml'};

const dictionaryKey = 'edicion-viva:latin-dictionary:v1';
const container = document.querySelector('#verses');
const wordPanel = document.querySelector('#word-panel');
const notePanel = document.querySelector('#note-panel');
const saveWordButton = document.querySelector('#save-word');
const drawer = document.querySelector('#side-drawer');
const tabs = Array.from(document.querySelectorAll('[data-drawer]'));
const appShell = document.querySelector('#app-shell');
const sidebar = document.querySelector('#sidebar');
const characterRail = document.querySelector('#character-rail');
let selected = null;
let noteAnchor = null;
let currentWord = null;
let activeDrawer = null;
let reviewDeck = [];
let reviewIndex = 0;
let savedWords = readDictionary();

function readDictionary() {
  try {
    const value = JSON.parse(localStorage.getItem(dictionaryKey) || '[]');
    return Array.isArray(value) ? value.filter(item => item && typeof item.id === 'string' &&
      typeof item.form === 'string' && typeof item.lemma === 'string' && typeof item.morphology === 'string') : [];
  } catch { return []; }
}

function persistDictionary() {
  try {
    localStorage.setItem(dictionaryKey, JSON.stringify(savedWords));
    return true;
  } catch {
    return false;
  }
}

function wordId(word) {
  return 'la|' + word[1].toLocaleLowerCase('la') + '|' + word[0].toLocaleLowerCase('la');
}

function updateSaveButton() {
  if (!currentWord) return;
  const exists = savedWords.some(item => item.id === wordId(currentWord.word));
  saveWordButton.textContent = exists ? '✓ Guardada · quitar' : '+ Guardar en mi diccionario';
  saveWordButton.setAttribute('aria-pressed', String(exists));
}

function positionPopover(anchor, popover) {
  if (!anchor || popover.hidden) return;
  const r = anchor.getBoundingClientRect();
  const p = popover.getBoundingClientRect();
  const margin = 12;
  const width = Math.min(p.width, window.innerWidth - margin * 2);
  let left = r.left - 22;
  left = Math.max(margin, Math.min(left, window.innerWidth - width - margin));
  let top = r.bottom + margin;
  if (top + p.height > window.innerHeight - margin && r.top > p.height + margin * 2) {
    top = r.top - p.height - margin;
  }
  top = Math.max(margin, Math.min(top, window.innerHeight - p.height - margin));
  popover.style.left = left + 'px';
  popover.style.top = top + 'px';
}

function closeWord() {
  if (selected) selected.setAttribute('aria-pressed','false');
  selected = null;
  currentWord = null;
  wordPanel.hidden = true;
}

function closeNote() {
  if (noteAnchor) noteAnchor.setAttribute('aria-expanded','false');
  noteAnchor = null;
  notePanel.hidden = true;
}

function setLatinParadigmLink(word) {
  const link = document.querySelector('#word-paradigm');
  const morphology = word[2] || '';
  // Plauto presenta también enclíticos, expresiones arcaicas y formas irregulares.
  const verb = /\bverbo\b|\bindicativo\b|\bsubjuntivo\b|\bimperativo\b|\binfinitivo\b|\bparticipio\b|\bgerundio\b|\bgerundivo\b|\bsupino\b|\bforma verbal\b/i.test(morphology);
  const nominal = /sustantivo|adjetivo|pronombre|determinante|artículo|nominativo|genitivo|dativo|acusativo|ablativo|vocativo/i.test(morphology);
  const type = verb ? 'conjugación' : nominal ? 'declinación' : 'entrada';
  const lemma = word[1].split(/\s+\+\s+/)[0].split(/\s*[,/]\s*/)[0];
  link.textContent = type === 'entrada' ? 'Ver entrada en Wiktionary ↗' :
    'Ver ' + type + ' en Wiktionary ↗';
  link.href = 'https://en.wiktionary.org/wiki/' + encodeURIComponent(lemma) + '#Latin';
  link.title = 'Consultar ' + lemma + ' en Wiktionary; las variantes arcaicas de Plauto pueden no figurar en el paradigma general.';
  link.hidden = false;
}

function openWord(button, word, reference) {
  closeNote();
  if (selected) selected.setAttribute('aria-pressed','false');
  selected = button;
  currentWord = { word, reference };
  button.setAttribute('aria-pressed','true');
  document.querySelector('#word-form').textContent = word[0];
  document.querySelector('#word-lemma').textContent = word[1];
  document.querySelector('#word-morphology').textContent = word[2];
  // Breve glosa española por lema, independiente del análisis morfológico.
  const gloss = word[3] || aululariaGlosses[word[1]];
  if (!gloss) throw new Error('Falta una traducción breve para el lema ' + word[1]);
  document.querySelector('#word-gloss').textContent = gloss;
  setLatinParadigmLink(word);
  wordPanel.hidden = false;
  updateSaveButton();
  positionPopover(button, wordPanel);
}

function openNote(button, note) {
  closeWord();
  closeNote();
  noteAnchor = button;
  button.setAttribute('aria-expanded','true');
  document.querySelector('#note-type').textContent = 'NOTA ' + note.number + ' · ' + note.type;
  document.querySelector('#note-heading').textContent = note.heading;
  document.querySelector('#note-content').textContent = note.text;
  notePanel.hidden = false;
  positionPopover(button, notePanel);
}

