notes['256'] = {number:256,type:'LENGUAJE JURÍDICO',heading:'La fórmula de la promesa',text:'La alternancia despondes / sponden / spondeo dramatiza el consentimiento verbal del matrimonio; la forma sponden incorpora la interrogativa enclítica -ne. Cotejo: Plauto, Aulularia 255–256, texto latino en https://www.thelatinlibrary.com/plautus/aulularia.shtml (consultado 12-XI-2026).'};
notes['259'] = {number:259,type:'LENGUA Y RETÓRICA',heading:'La desconfianza convertida en juego verbal',text:'perplexarier conserva la terminación arcaica -ier de infinitivo; el juego pactum non pactum / non pactum pactum invierte las fórmulas del acuerdo para expresar el temor de Euclión a que se alteren sus condiciones. Plauto, Aulularia 259–260, https://www.thelatinlibrary.com/plautus/aulularia.shtml. La clasificación exacta de perplexarier requiere cotejo léxico adicional.'};
notes['250'] = {number:250,type:'SINTAXIS Y HUMOR',heading:'Gerundivos de castigo',text:'elinguandam dedero y castrandum loces emplean gerundivos acusativos que expresan la finalidad de entregar a alguien para recibir un castigo. El juramento de Euclión es una hipérbole dirigida a Estáfila, no una orden efectiva. Cotejo: Plauto, Aulularia 250–251, Friedrich Leo, Plauti Comoediae I (1895), Perseus Digital Library, https://beta.perseus.tufts.edu/urn:cts:latinLit:phi0119.phi003.perseus-lat2/; análisis de la construcción en Rosemarie Lühr, Konkurrenzsyntax I, §2.6.7, https://dwee.saw-leipzig.de/Rosemarie_Luehr/userfiles/downloads/Projekte/PlautusAulularia.pdf.'};
notes['251'] = {number:251,type:'CRÍTICA TEXTUAL',heading:'Un ego suplementado',text:'En la transcripción de The Latin Library el pronombre ego aparece entre corchetes angulares, como suplemento editorial. Se presenta aquí sin marcas en la línea de lectura, pero no se atribuye sin reserva a la transmisión. Comparar https://www.thelatinlibrary.com/plautus/aulularia.shtml, Aulularia 251. Cotejo del aparato impreso de Leo pendiente.'};
notes['244–245'] = {number:244,type:'LÉXICO Y DRAMATURGIA',heading:'El desaire interpretado',text:'Megadoro interpreta la huida de Euclión como un rechazo social. certiorem facere significa informar o poner al corriente; fastidit mei construye el verbo de desdén con genitivo personal. Plauto, Aulularia 244–246; Friedrich Leo, Plauti comoediae (1895), edición digital Perseus, https://beta.perseus.tufts.edu/urn:cts:latinLit:phi0119.phi003.perseus-lat2/; cotejo https://www.thelatinlibrary.com/plautus/aulularia.shtml.'};
notes['247'] = {number:247,type:'MORFOLOGÍA',heading:'Supino de finalidad',text:'petitum es supino en -um de peto, dependiente del verbo de movimiento it: «va a buscar». La secuencia pauperioris gratiam expresa el favor del más pobre; no debe confundirse el supino con un participio. Plauto, Aulularia 247–249; Leo (1895), https://beta.perseus.tufts.edu/urn:cts:latinLit:phi0119.phi003.perseus-lat2/; https://www.thelatinlibrary.com/plautus/aulularia.shtml.'};


notes['328'] = {number:328,type:'CRÍTICA TEXTUAL',heading:'Texto suplementado y numeración 328a',text:'El texto de «cape atque abi intro ad nos» y «quem illic reliquit agnum» se transmite en la edición digital consultada entre corchetes angulares: es suplemento editorial, no debe considerarse testimonio íntegro. El número 328a distingue una línea intercalada en la numeración del pasaje. El comienzo de 329 contiene una laguna marcada por asteriscos, que aquí no se reconstruye. Cotejo: Plauto, Aulularia II.5, 327–330, https://www.thelatinlibrary.com/plautus/aulularia.shtml. Aparato de Leo (1895) pendiente de comprobación directa.'};
notes['330'] = {number:330,type:'LÉXICO',heading:'Iniuria',text:'Iniuria puede funcionar adverbialmente, «injustamente», a partir del ablativo de iniuria; Congrión protesta por el reparto desigual de los corderos. Plauto, Aulularia II.5, 330–331, https://www.thelatinlibrary.com/plautus/aulularia.shtml.'};

notes['336'] = {number:336,type:'LÉXICO Y COMICIDAD',heading:'Hasta quedarse ronco',text:'Usque ad ravim describe una insistencia que desemboca en la ronquera; la repetición de poscam intensifica la queja del cocinero. Texto: Plauto, Aulularia II.5, 336–337, https://www.thelatinlibrary.com/plautus/aulularia.shtml. Aparato crítico de Leo pendiente.'};
notes['341'] = {number:341,type:'MORFOLOGÍA',heading:'Adferto y la orden práctica',text:'Adferto es imperativo futuro de adfero en -to, frecuente en órdenes y prescripciones; abs te conserva la variante preposicional abs. La advertencia vuelve absurda la tarea del cocinero: deberá llevar desde su propia casa lo que necesite. Plauto, Aulularia II.5, 339–341; texto cotejado https://www.thelatinlibrary.com/plautus/aulularia.shtml; Leo, Plauti comoediae I (1895), https://scaife.perseus.org/library/urn:cts:latinLit:phi0119.phi003/.'};

// Numeración de II.1: los dos versos métricos 142–143 permanecen en una unidad
// para conservar el texto y los offsets de resaltados del ID histórico v142.
// Los versos siguientes conservan IDs v143–v159, aunque muestran 144–160.
for (let oldN = 159; oldN >= 143; oldN--) {
  const key = String(oldN);
  if (notes[key]) { notes[String(oldN + 1)] = notes[key]; delete notes[key]; }
}
if (notes['142']) notes['142'].text += ' La unidad conjunta conserva, por compatibilidad de resaltados, los versos métricos 142–143 (Da mihi operam amabo / Tuast, utere atque impera, si quid vis). Véase Plauto, Aulularia II.1, https://www.thelatinlibrary.com/plautus/aulularia.shtml; Goetz y Schoell, Comoediae I (1898), https://resources.warburg.sas.ac.uk/pdf/eph720b2450290.pdf.';
if (notes['162']) notes['162'].text += ' En el v. 162, media es acusativo femenino singular de medius y califica a uxorem; su repetición con mediam aetatem crea el juego verbal. Goetz y Schoell (1898, ad 162) registran además la variante mediam transmitida por Festo.';
notes['167'] = {number:'167–169',type:'HISTORIA Y ESCENA',heading:'El catálogo de lujo de Megadoro',text:'Las factiones, dotes dapsiles, eburata vehicla, pallas y purpuram representan las exigencias y símbolos de prestigio que Megadoro asocia con una esposa rica. La servidumbre económica del marido es una hipérbole cómica. La posible resonancia de debates romanos sobre el lujo no equivale a una identificación histórica segura. Texto: Plauto, Aulularia II.1, 167–169, https://www.thelatinlibrary.com/plautus/aulularia.shtml. Lectura: «Plautus – the catalogue of the dress dealers in the Aulularia», https://doi.org/10.1515/9783110711554-007.'};
notes['169'] = {number:169,type:'SINTAXIS',heading:'Quae como sujeto',text:'Quae es relativo neutro nominativo plural y sujeto de redigunt: resume los lujos enumerados antes. Sumptibus funciona como ablativo de medio o causa. Plauto, Aulularia II.1, 167–169, https://www.thelatinlibrary.com/plautus/aulularia.shtml.'};

// Consolidación de orden de lectura para la unidad 225–264. El número 244–245
// corresponde a UNA fila editorial con ambos números; por eso son 39 filas para
// 40 números canónicos. Se conservan intactos los IDs y los offsets de resaltados.
{
  const inRange = entry => entry.n === '244–245' || /^\d+$/.test(entry.n) && Number(entry.n) >= 225 && Number(entry.n) <= 264;
  const block = verses.filter(inRange);
  const keys = new Set(block.map(entry => entry.n));
  const expected = [...Array.from({length:40},(_, i)=>String(225+i)).filter(n=>n!=='244'&&n!=='245'), '244–245'];
  const insertAfter = verses.findIndex(entry => entry.n === '224');
  if (block.length === 39 && keys.size === 39 && expected.every(n=>keys.has(n)) && insertAfter >= 0) {
    for (let i = verses.length-1; i >= 0; i--) if(inRange(verses[i])) verses.splice(i,1);
    const at = verses.findIndex(entry=>entry.n === '224')+1;
    block.sort((a,b)=>parseInt(a.n,10)-parseInt(b.n,10));
    verses.splice(at,0,...block);
  } else {
    console.error('Aulularia: bloque II.2 225–264 no reordenado por datos incompletos.');
  }
}
// Reordenación de II.2: el bloque 212–225 fue incorporado después de 226–227.
// Esta operación conserva el contenido, los IDs v212–v227 y sus offsets.
{
  const block = verses.filter(entry => Number(entry.n) >= 212 && Number(entry.n) <= 225);
  const insertAt = verses.findIndex(entry => entry.n === '226');
  const unique = new Set(block.map(entry => entry.n));
  if (block.length === 14 && unique.size === 14 && insertAt >= 0) {
    for (let i = verses.length - 1; i >= 0; i--) {
      if (Number(verses[i].n) >= 212 && Number(verses[i].n) <= 225) verses.splice(i, 1);
    }
    const target = verses.findIndex(entry => entry.n === '226');
    block.sort((a, b) => Number(a.n) - Number(b.n));
    verses.splice(target, 0, ...block);
  } else {
    console.error('Aulularia: no se reordenaron los versos 212–225 por posible conflicto editorial.');
  }
}
// Los IDs históricos de resaltados no se modifican. La numeración canónica 186–190
// contiene dos filas para 186 y una sola fila conjunta para 189–190.
for (const entry of verses) {
  if (entry.n === '187') { entry.displayNumber = '186 (cont.)'; entry.referenceNumber = '186'; }
  if (entry.n === '188') { entry.displayNumber = '187'; entry.referenceNumber = '187'; }
  if (entry.n === '189') { entry.displayNumber = '188'; entry.referenceNumber = '188'; }
  if (entry.n === '190') { entry.displayNumber = '189–190'; entry.referenceNumber = '189–190'; }
}
notes['186'] = {number:186,type:'MÉTRICA Y LENGUA',heading:'Una línea, dos interlocutores',text:'Ain tu te valere? / Pol ego haud perbene a pecunia son dos intervenciones del mismo verso métrico 186. Para no invalidar resaltados, la lectura conserva dos filas históricas y marca la segunda como continuación. El giro a pecunia especifica el ámbito en el que Euclión declara no encontrarse bien, pese a poseer oro. Edición cotejada: Plauto, Aulularia II.2, vv. 185–187, https://www.thelatinlibrary.com/plautus/aulularia.shtml; contraste https://www.lateinlex.de/?call=Puc&permalink=Plaut_Aul_II_II.'};
notes['197'] = {number:197,type:'LÉXICO Y COMICIDAD',heading:'Zamia y el pulpo',text:'Zamia, préstamo del griego ζημία (perjuicio, daño), aparece como ablativo instrumental de onerat: quien parece ofrecer ayuda acaba cargando al pobre con un costo. El v. 198 prolonga la imagen con polypos, los pulpos que se aferran a cuanto tocan. Texto y posición: Plauto, Aulularia II.2, 197–198, https://www.thelatinlibrary.com/plautus/aulularia.shtml; Joanne Walker, A commentary on Plautus’ Aulularia (2005), https://hdl.handle.net/10023/14536.'};
notes['213'] = {number:213,type:'SINTAXIS',heading:'El ablativo elíptico bona',text:'En la serie quid fide? — bona, bona es ablativo singular femenino, con fide sobreentendido, no nominativo. La siguiente respuesta neque malis neque improbis continúa la elipsis ablativa de factis. Texto cotejado: Plauto, Aulularia II.2, 212–214, https://www.lateinlex.de/?call=Puc&permalink=Plaut_Aul_II_II.'};
notes['216'].text += ' Aurum es nominativo neutro, sujeto de olet, no acusativo directo; huic corresponde al dativo. Esta construcción sostiene el chiste del aparte.';
// La nota preexistente del verso 223 sobre derisum venio se conserva sin sustitución.

// Nuevas precisiones filológicas cotejadas en la segunda pasada (225–264).
notes['228'] = {number:228,type:'MORFOLOGÍA',heading:'Locassim y la condición prospectiva',text:'Locassim conserva la flexión arcaica en -assim de loco, donde se sustituyó -av- del tema perfecto. Como otros futuros perfectos y perfectos de subjuntivo, la forma es homógrafa: la condición con si proyecta un matrimonio hipotético; no se debe confundir con presente indicativo. Contexto: Plauto, Aulularia II.2, 228–230, https://www.lateinlex.de/?call=Puc&permalink=Plaut_Aul_II_II. Para formas sigmáticas del latín arcaico, W. D. C. de Melo, The Early Latin Verb System (2007), https://doi.org/10.1093/acprof:oso/9780199209026.001.0001.'};
notes['227'] = {number:227,type:'CRÍTICA TEXTUAL',heading:'Me autem / me item',text:'En 227 la edición de Leo lee me autem, mientras otras ediciones imprimen me item. Se conserva la lección de la fuente base sin eliminar la variante, que afecta el contraste entre la riqueza de Megadoro y la pobreza de Euclión. Textos: Plauto, Aulularia II.2, 226–227, https://www.thelatinlibrary.com/plautus/aulularia.shtml; edición alternativa en https://www.mqdq.it/testo/testo/codice/PLAVT%7Caulu%7C001.'};
notes['251'].text += ' Además, el contraste de géneros en te elinguandam (v. 250, referido a Estáfila) y me castrandum (v. 251, referido a Euclión) determina la interpretación del parlamento. El juramento se dirige a la esclava dentro de casa; Megadoro lo malinterpreta como posible insulto. Cf. J. Walker, A Commentary on Plautus Aulularia, tesis de St Andrews (2005), comentario a 250–254, https://hdl.handle.net/10023/14536.';
notes['259'].text += ' La terminación -ier es una variante morfológica de infinitivo medio-pasivo arcaico: el análisis en la ficha advierte la ambigüedad de su interpretación reflexiva. No confundir la forma con un futuro simple ni con infinitivo activo.';
notes['264'] = {number:264,type:'CRÍTICA TEXTUAL',heading:'¿Pythodice o Strobile?',text:'Friedrich Leo (1895) imprime Pythodice en 264, lectura editorial que distingue al esclavo de Megadoro del de Licónides. La tradición manuscrita transmite Strobile, según Joanne Walker, A Commentary on Plautus Aulularia (2005), introducción pp. 5–7 y comentario ad 264; Walker defiende conservar Strobile y discute el problemático encabezamiento FITODICUS de 363. La atribución del nombre no es segura. Referencias: https://hdl.handle.net/10023/14536 y https://www.thelatinlibrary.com/plautus/aulularia.shtml. Se mantiene Pythodice por fidelidad a la edición base Leo (1895).'};

// Aulularia, segunda revisión filológica (265–304): variantes, glosas de hablantes y dramaturgia.
notes['265'] = {number:265,type:'DRAMATURGIA Y SINTAXIS',heading:'Aurum quid valet',text:'El exclamativo aurum quid valet expresa la convicción obsesiva de Euclión de que el oro mueve las intenciones de Megadoro. Aurum es nominativo sujeto de valet y quid introduce la exclamación de grado, no una pregunta indirecta. El personaje confunde su conjetura con un hecho. Texto: Plauto, Aulularia II.2, 265–267, https://www.thelatinlibrary.com/plautus/aulularia.shtml.'};
notes['266'].text += ' Maclennan y Stockert, Plautus: Aulularia (Liverpool University Press, 2016), aparato a 266, registran la exclusión editorial del verso por Leo (del. Leo). Los corchetes señalan su situación crítica, no un suplemento que pueda considerarse seguro; se mantiene la lectura de la edición base para documentar la decisión.';
notes['274'] = {number:274,type:'LECTURA Y ESCENA',heading:'La intervención de Estáfila',text:'La sigla STAPH. de la fuente digital introduce un cambio de personaje en mitad del verso; en el lector se conserva dentro de la línea para no alterar los offsets de los resaltados y se ofrece una ficha que la identifica como rótulo editorial. La pregunta quid ego nunc agam abre el soliloquio temeroso de Estáfila. Texto: Plauto, Aulularia II.3, 273–275, https://www.thelatinlibrary.com/plautus/aulularia.shtml.'};
notes['285'].text += ' La distribución manuscrita de los parlamentos presenta dificultades: Maclennan y Stockert (2016), aparato a 285 y 287, consignan CON. como atribución de Bothe frente a STR. en P para 285, y STR. de Camerarius frente a COC. en P para 287. Aquí se siguen las atribuciones de la lectura editorial de Leo, sin ocultar la discrepancia; https://dokumen.pub/plautus-aulularia-1910572373-9781910572375.html.';
notes['287'].text += ' En 288, Leo lee quo, pero el aparato de Maclennan y Stockert (2016), ad 288, registra quod en los manuscritos (P): diferencia textual relevante para el análisis sintáctico. Se mantiene quo de la fuente base y se marca la incertidumbre. https://dokumen.pub/plautus-aulularia-1910572373-9781910572375.html.';
notes['296'] = {number:296,type:'GRAMÁTICA Y EDICIÓN',heading:'Quid negotist y las siglas',text:'Quid negotist contrae quid negoti est: el genitivo partitivo de negotium acompaña a quid. Quid negoti sit rogas incorpora una interrogativa indirecta con el subjuntivo sit. Las siglas ANTHR. y PYTH. son marcas editoriales del cambio de interlocutor, no palabras latinas del verso; sus fichas lo indican explícitamente. Texto cotejado: Plauto, Aulularia II.4, 293–297, https://www.thelatinlibrary.com/plautus/aulularia.shtml.'};
notes['298'].text += ' Maclennan y Stockert (2016), aparato a 298, atribuyen a Havet la indicación de una laguna después de este verso (post 298 lacunam indicavit Havet). Por tanto, el inicio de 299 queda sintácticamente truncado; los puntos suspensivos de la traducción señalan la pérdida, no aportan texto nuevo. https://dokumen.pub/plautus-aulularia-1910572373-9781910572375.html.';
notes['304'].text += ' En la réplica, gutturem muestra acusativo masculino donde el nombre clásico guttur, gutturis se considera generalmente neutro; el comentario de forma ha de distinguirse del valor obsceno del sintagma. Texto: Plauto, Aulularia II.4, 304–305, https://www.thelatinlibrary.com/plautus/aulularia.shtml.';

let lastNumber = '';
let previousSpeaker = '';
let previousSection = '';
for (const entry of verses) {
  if (entry.n) lastNumber = entry.n;
  const row = document.createElement('div');
  row.className = 'verse';
  row.id = entry.stableId || ('v' + (entry.n || lastNumber + '-continuation'));
  const left = document.createElement('div');
  left.className = 'latin-side';
  const num = document.createElement('span');
  num.className = 'number';
  num.textContent = entry.displayNumber || entry.n;
  const speech = document.createElement('div');
  speech.className = 'speech';
  // El nombre encabeza el parlamento, no cada verso del mismo hablante.
  // Una nueva escena vuelve a mostrarlo; las intervenciones mixtas conservan su rótulo.
  const currentSection = entry.section || (Number(lastNumber) <= 39 ? 'prologue' : 'legacy');
  const currentSpeaker = (entry.speaker || '').trim();
  if (currentSpeaker && (currentSpeaker !== previousSpeaker || currentSection !== previousSection || currentSpeaker.includes('/'))) {
    const who = document.createElement('span');
    who.className = 'speaker';
    who.textContent = currentSpeaker;
    speech.append(who);
  }
  previousSpeaker = currentSpeaker;
  previousSection = currentSection;
  const latin = document.createElement('p');
  latin.className = 'latin';
  const reference = (Number(lastNumber) <= 39 ? 'Prólogo' : Number(lastNumber) <= 78 ? 'I.1' : Number(lastNumber) <= 119 ? 'I.2' : Number(lastNumber) <= 177 ? 'II.1' : 'II.2') + ', v. ' + (entry.referenceNumber || lastNumber);
  const chunks = entry.latin.match(/\p{L}+|[^\p{L}]+/gu) || [];
  let index = 0;
  for (const chunk of chunks) {
    if (!/^\p{L}/u.test(chunk)) {
      latin.append(document.createTextNode(chunk));
      continue;
    }
    const word = entry.words[index++];
    if (!word || word[0].toLocaleLowerCase('la') !== chunk.toLocaleLowerCase('la')) {
      // Un desajuste editorial no debe dejar vacía toda la obra.
      // La palabra permanece visible y pulsable, señalada explícitamente como pendiente.
      console.error('Aulularia: ficha desalineada', {verso: entry.n, forma: chunk, ficha: word});
      const pending = document.createElement('button');
      pending.type = 'button';
      pending.className = 'token token-pending';
      pending.textContent = chunk;
      pending.title = 'Ficha morfológica pendiente de corrección';
      pending.setAttribute('aria-label', chunk + ': ficha pendiente de corrección');
      pending.addEventListener('click', () => {
        document.querySelector('#word-form').textContent = chunk;
        document.querySelector('#word-lemma').textContent = 'Pendiente de cotejo';
        document.querySelector('#word-morphology').textContent = 'Esta ficha presenta un desajuste editorial y requiere revisión.';
        document.querySelector('#word-gloss').textContent = 'Glosa pendiente';
        document.querySelector('#word-paradigm').hidden = true;
        wordPanel.hidden = false;
        positionPopover(pending, wordPanel);
      });
      latin.append(pending);
      continue;
    }
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'token';
    button.textContent = chunk;
    button.setAttribute('aria-label', chunk + ': ver análisis morfológico');
    button.setAttribute('aria-pressed','false');
    const tokenReference = entry.displayNumber === '142–143' && index > 4 ? 'II.1, v. 143' : entry.n === '190' ? 'II.2, v. ' + (index <= 9 ? '189' : '190') : reference;
    button.addEventListener('click', () => openWord(button, word, tokenReference));
    latin.append(button);
  }
  if (index !== entry.words.length) console.error('Aulularia: fichas sobrantes', {verso: entry.n, fichas: entry.words.length, tokens: index});
  const note = notes[entry.n];
  if (note) {
    latin.append(document.createTextNode(' '));
    const noteButton = document.createElement('button');
    noteButton.type = 'button';
    noteButton.className = 'note-anchor';
    noteButton.textContent = String(note.number);
    noteButton.setAttribute('aria-label', 'Nota ' + note.number + ': ' + note.heading);
    noteButton.setAttribute('aria-expanded','false');
    noteButton.addEventListener('click', () => openNote(noteButton, note));
    latin.append(noteButton);
  }
  speech.append(latin);
  left.append(num,speech);
  const right = document.createElement('p');
  right.className = 'spanish';
  right.textContent = entry.spanish;
  row.append(left,right);
  row.dataset.section = entry.section || (Number(lastNumber) <= 39 ? 'prologue' : Number(lastNumber) <= 78 ? 'act1scene1' : Number(lastNumber) <= 119 ? 'act1scene2' : Number(lastNumber) <= 177 ? 'act2scene1' : 'act2scene2');
  container.append(row);
}

saveWordButton.addEventListener('click', () => {
  if (!currentWord) return;
  const id = wordId(currentWord.word);
  const before = savedWords.slice();
  const index = savedWords.findIndex(item => item.id === id);
  if (index >= 0) savedWords.splice(index, 1);
  else savedWords.push({
    id, language: 'latín', form: currentWord.word[0], lemma: currentWord.word[1],
    morphology: currentWord.word[2], work: 'Plauto · Aulularia',
    reference: currentWord.reference, addedAt: new Date().toISOString()
  });
  if (!persistDictionary()) {
    savedWords = before;
    saveWordButton.textContent = 'No se pudo guardar en este navegador';
    return;
  }
  updateSaveButton();
  renderDictionary();
});

function renderDictionary() {
  document.querySelector('#saved-count').textContent = String(savedWords.length);
  document.querySelectorAll('.mobile-saved-count').forEach(node => node.textContent = savedWords.length ? '(' + savedWords.length + ')' : '');
  document.querySelector('#start-review').disabled = !savedWords.length;
  document.querySelector('#export-dictionary').disabled = !savedWords.length;
  const list = document.querySelector('#dictionary-list');
  list.replaceChildren();
  if (!savedWords.length) {
    const empty = document.createElement('p');
    empty.className = 'dictionary-empty';
    empty.textContent = 'Todavía no hay palabras guardadas. Seleccioná una palabra del latín y elegí «Guardar».';
    list.append(empty);
    return;
  }
  for (const item of savedWords) {
    const article = document.createElement('article');
    article.className = 'dictionary-entry';
    const content = document.createElement('div');
    const form = document.createElement('strong');
    form.textContent = item.form;
    const lemma = document.createElement('span');
    lemma.textContent = item.lemma + ' · ' + item.reference;
    content.append(form,lemma);
    const remove = document.createElement('button');
    remove.type = 'button';
    remove.textContent = '×';
    remove.setAttribute('aria-label', 'Quitar ' + item.form + ' del diccionario');
    remove.addEventListener('click', () => {
      const before = savedWords.slice();
      savedWords = savedWords.filter(word => word.id !== item.id);
      if (!persistDictionary()) { savedWords = before; return; }
      renderDictionary();
      updateSaveButton();
    });
    article.append(content,remove);
    list.append(article);
  }
}

function closeDrawer() {
  activeDrawer = null;
  drawer.hidden = true;
  sidebar.classList.remove('open');
  characterRail.classList.remove('open');
  tabs.filter(tab => tab.dataset.drawer === 'dictionary').forEach(tab => tab.setAttribute('aria-expanded','false'));
  document.querySelector('#flashcard').hidden = true;
  document.querySelector('#dictionary-list').hidden = false;
  syncPanelButtons();
}
function syncPanelButtons() {
  const compact = window.matchMedia('(max-width: 1160px)').matches;
  const mobile = window.matchMedia('(max-width: 860px)').matches;
  tabs.forEach(tab => {
    const type = tab.dataset.drawer;
    let expanded = type === 'dictionary' ? activeDrawer === 'dictionary' :
      type === 'position' ? (mobile ? sidebar.classList.contains('open') : !appShell.classList.contains('nav-collapsed')) :
      (compact ? characterRail.classList.contains('open') : !appShell.classList.contains('characters-collapsed'));
    tab.setAttribute('aria-expanded', String(expanded));
  });
}
function openDrawer(name) {
  closeWord();
  closeNote();
  const compact = window.matchMedia('(max-width: 1160px)').matches;
  const mobile = window.matchMedia('(max-width: 860px)').matches;
  if (name === 'position') {
    const wasOpen = mobile ? sidebar.classList.contains('open') : !appShell.classList.contains('nav-collapsed');
    closeDrawer();
    if (mobile) sidebar.classList.toggle('open', !wasOpen);
    else appShell.classList.toggle('nav-collapsed', wasOpen);
    syncPanelButtons();
    return;
  }
  if (name === 'characters') {
    const wasOpen = compact ? characterRail.classList.contains('open') : !appShell.classList.contains('characters-collapsed');
    closeDrawer();
    if (compact) characterRail.classList.toggle('open', !wasOpen);
    else appShell.classList.toggle('characters-collapsed', wasOpen);
    syncPanelButtons();
    return;
  }
  const wasOpen = activeDrawer === 'dictionary';
  closeDrawer();
  if (!wasOpen && name === 'dictionary') {
    activeDrawer = name;
    drawer.hidden = false;
    renderDictionary();
  }
  syncPanelButtons();
}
tabs.forEach(tab => tab.addEventListener('click', () => openDrawer(tab.dataset.drawer)));
document.querySelector('#close-drawer').addEventListener('click', closeDrawer);
document.querySelector('#return-to-text').addEventListener('click', closeDrawer);
document.querySelector('#close-word').addEventListener('click', closeWord);
document.querySelector('#close-note').addEventListener('click', closeNote);

document.querySelector('#export-dictionary').addEventListener('click', () => {
  if (!savedWords.length) return;
  const blob = new Blob([JSON.stringify({version:1, words:savedWords},null,2)], {type:'application/json'});
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = 'edicion-viva-diccionario.json';
  document.body.append(link);
  link.click();
  link.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
});
document.querySelector('#import-trigger').addEventListener('click', () => document.querySelector('#import-dictionary').click());
document.querySelector('#import-dictionary').addEventListener('change', async event => {
  const file = event.target.files?.[0];
  if (!file) return;
  const feedback = document.querySelector('#dictionary-feedback');
  try {
    const data = JSON.parse(await file.text());
    if (data.version !== 1 || !Array.isArray(data.words)) throw new Error('Formato no reconocido');
    const incoming = data.words.filter(item => item && typeof item.id === 'string' &&
      typeof item.form === 'string' && typeof item.lemma === 'string' && typeof item.morphology === 'string');
    const before = savedWords.slice();
    const known = new Set(savedWords.map(item => item.id));
    let count = 0;
    for (const item of incoming) {
      if (!known.has(item.id)) { savedWords.push(item); known.add(item.id); count++; }
    }
    if (!persistDictionary()) { savedWords = before; throw new Error('No se pudo guardar'); }
    feedback.textContent = count + ' palabra(s) importada(s).';
    renderDictionary();
  } catch {
    feedback.textContent = 'No se pudo importar ese archivo JSON.';
  }
  event.target.value = '';
});

function showCard() {
  const card = reviewDeck[reviewIndex];
  document.querySelector('#flash-progress').textContent = (reviewIndex + 1) + ' de ' + reviewDeck.length;
  document.querySelector('#flash-form').textContent = card.form;
  document.querySelector('#flash-lemma').textContent = card.lemma;
  document.querySelector('#flash-morph').textContent = card.morphology;
  document.querySelector('#flash-answer').hidden = true;
  document.querySelector('#reveal-card').hidden = false;
  document.querySelector('#next-card').hidden = true;
}

document.querySelector('#start-review').addEventListener('click', () => {
  reviewDeck = savedWords.slice();
  if (!reviewDeck.length) return;
  reviewIndex = 0;
  document.querySelector('#dictionary-list').hidden = true;
  document.querySelector('#flashcard').hidden = false;
  showCard();
});
document.querySelector('#reveal-card').addEventListener('click', () => {
  document.querySelector('#flash-answer').hidden = false;
  document.querySelector('#reveal-card').hidden = true;
  document.querySelector('#next-card').hidden = false;
});
document.querySelector('#next-card').addEventListener('click', () => {
  reviewIndex = (reviewIndex + 1) % reviewDeck.length;
  showCard();
});
document.querySelector('#end-review').addEventListener('click', () => {
  document.querySelector('#flashcard').hidden = true;
  document.querySelector('#dictionary-list').hidden = false;
  renderDictionary();
});

function trackAnchor() {
  for (const [anchor, popover] of [[selected,wordPanel],[noteAnchor,notePanel]]) {
    if (!anchor || popover.hidden) continue;
    const r = anchor.getBoundingClientRect();
    if (r.bottom < 0 || r.top > window.innerHeight) {
      popover === wordPanel ? closeWord() : closeNote();
    } else positionPopover(anchor,popover);
  }
}
window.addEventListener('scroll', trackAnchor, {passive:true});
window.addEventListener('resize', trackAnchor);
document.addEventListener('pointerdown', event => {
  if (!wordPanel.hidden && !wordPanel.contains(event.target) && !event.target.closest('.token')) closeWord();
  if (!notePanel.hidden && !notePanel.contains(event.target) && !event.target.closest('.note-anchor')) closeNote();
  if (!drawer.hidden && !drawer.contains(event.target) && !event.target.closest('.side-tabs')) closeDrawer();
});
document.addEventListener('keydown', event => {
  if (event.key === 'Escape') {
    closeWord();
    closeNote();
    closeDrawer();
  }
});
renderDictionary();
syncPanelButtons();
window.addEventListener('edicion-viva:dictionary-updated', event => {
  if (event.detail?.language !== 'la') return;
  savedWords = readDictionary();
  renderDictionary();
  updateSaveButton();
});
window.addEventListener('resize', syncPanelButtons);

/* Navegación editorial: se deriva de las secciones realmente publicadas.
   Los futuros bloques pueden declarar entry.section y se incorporan sin editar el menú. */
const sectionNames = {
  prologue: 'Prólogo · Lar familiar',
  fragmenta: 'Fragmentos I–V · ubicación incierta', dubia: 'Fragmento dudoso · atribución incierta',
  act1scene1: 'Acto I, escena 1', act1scene2: 'Acto I, escena 2',
  act2scene1: 'Acto II, escena 1', act2scene2: 'Acto II, escena 2',
  act2scene3: 'Acto II, escena 3', act2scene4: 'Acto II, escena 4',
  act2scene5: 'Acto II, escena 5', act2scene6: 'Acto II, escena 6',
  act2scene7: 'Acto II, escena 7', act2scene8: 'Acto II, escena 8',
  act2scene9: 'Acto II, escena 9', act3scene1: 'Acto III, escena 1',
  act3scene2: 'Acto III, escena 2', act3scene3: 'Acto III, escena 3',
  act3scene4: 'Acto III, escena 4', act3scene5: 'Acto III, escena 5'
};
const sectionRanges = new Map();
for (const row of container.querySelectorAll('.verse[data-section]')) {
  const section = row.dataset.section;
  const raw = row.querySelector('.number')?.textContent || '';
  const numbers = (raw.match(/\d+/g) || []).map(Number);
  if (!sectionRanges.has(section)) sectionRanges.set(section, []);
  sectionRanges.get(section).push(...numbers);
}
const navSlot = document.querySelector('#section-nav-slot');
const oldActLabel = navSlot.previousElementSibling;
if (oldActLabel?.classList.contains('act-label')) oldActLabel.hidden = true;
const sectionNav = document.createElement('nav');
sectionNav.className = 'section-navigation';
sectionNav.setAttribute('aria-label', 'Actos y escenas');
const navButtons = new Map();
const navGroups = new Map();
const roman = ['','I','II','III','IV','V'];
function makeGroup(act) {
  const heading = document.createElement('button');
  heading.type = 'button';
  heading.className = 'act-nav-toggle';
  heading.textContent = act === 'prologue' ? 'PRÓLOGO' : act === 'other' ? 'FRAGMENTOS Y LAGUNAS' : 'ACTO ' + (roman[Number(act)] || act);
  const scenes = document.createElement('div');
  scenes.className = 'act-nav-scenes';
  const groupId = 'aulularia-scenes-' + act;
  scenes.id = groupId;
  heading.setAttribute('aria-controls', groupId);
  heading.setAttribute('aria-expanded', 'true');
  heading.addEventListener('click', () => {
    scenes.hidden = !scenes.hidden;
    heading.setAttribute('aria-expanded', String(!scenes.hidden));
  });
  sectionNav.append(heading, scenes);
  navGroups.set(act, {heading, scenes});
  return scenes;
}
for (const [section, numbers] of sectionRanges) {
  const match = section.match(/^act(\d+)scene(\d+)$/);
  const act = section === 'prologue' ? 'prologue' : match?.[1] || 'other';
  const scenes = navGroups.get(act)?.scenes || makeGroup(act);
  const button = document.createElement('button');
  button.type = 'button';
  button.className = 'scene-nav-button';
  button.dataset.section = section;
  const name = sectionNames[section] || section.replace(/^act(\d+)scene(\d+)$/, 'Acto $1, escena $2');
  const range = (section === 'fragmenta' || section === 'dubia') ? '' : numbers.length ? ' · vv. ' + Math.min(...numbers) + '–' + Math.max(...numbers) : '';
  button.textContent = (section === 'prologue' ? 'Lar familiar' : match ? 'Escena ' + match[2] : name) + range;
  button.addEventListener('click', () => selectSection(section));
  scenes.append(button);
  navButtons.set(section, button);
}
navSlot.append(sectionNav);
function selectSection(section) {
  for (const row of container.querySelectorAll('.verse')) row.hidden = row.dataset.section !== section;
  for (const [id, button] of navButtons) {
    button.classList.toggle('active', id === section);
    if (id === section) button.setAttribute('aria-current', 'true');
    else button.removeAttribute('aria-current');
  }
  const act = section === 'prologue' ? 'prologue' : section.match(/^act(\d+)scene/)?.[1] || 'other';
  const parent = navGroups.get(act);
  if (parent?.scenes.hidden) {
    parent.scenes.hidden = false;
    parent.heading.setAttribute('aria-expanded', 'true');
  }
  const name = sectionNames[section] || section.replace(/^act(\d+)scene(\d+)$/, 'Acto $1, escena $2');
  const current = document.querySelector('.position-current');
  if (current) current.textContent = name;
  const numbers = sectionRanges.get(section) || [];
  const marker = document.querySelector('.position-marker strong');
  if (marker && numbers.length) marker.textContent = 'vv. ' + Math.min(...numbers) + '–' + Math.max(...numbers);
  closeWord(); closeNote();
}
if (sectionRanges.size) selectSection(sectionRanges.keys().next().value);
